  Summon_100429_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:勝利の夜>】限定命輪イベント覚醒中、SSRアイテムを獲得する基本確率は3.03％、総合確率(保底を含む)は5.02％です。獲得したSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底によりSSR命輪を獲得できます。\n·覚醒でSSR命輪を獲得した際、50.00％の確率で今回のUPのSSR命輪<SummonOrange:幸運の時>となります。\n·前回の覚醒で獲得したSSR命輪が今回の確率アップ命輪でない場合、次回の覚醒で獲得するSSR命輪は必ず今回の確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:勝利の夜>】命輪イベント覚醒中、SRアイテムの覚醒基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を獲得した場合、同時に50個の根源の澱を副産物として獲得します；SR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の獲得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱は変換されません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
