  Summon_117217_Desc = {
    Text = "期間限定イベントで、<SummonOrange:5>回までしか呼び出せない！"
  },
  Summon_117217_LongDesc1 = {
    Text = "【<SummonOrange:群星との邂逅·防御型>】運命の軌道連合覚醒が開放されました。開放期間中、守秘者は1体の星辰篇防御型SSR覚醒体、1体の忘却篇防御型SSR覚醒体、1個の星辰篇防御型覚醒体推薦SSR命輪、2個の忘却篇防御型覚醒体推薦SSR命輪をランダムに覚醒させることができます。\n·各運命の軌道連合覚醒は5回の覚醒後に終了します。\n·今回の運命の軌道連合覚醒イベントでは、毎回の覚醒で必ずランダムSSR覚醒体またはランダムSSR命輪を獲得できます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、覚醒体や命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは限時のリバース機能を開放し、覚醒体や命輪の育成または覚醒に再配置リソースの機会を提供します。\n·この点を理解し、受け入れた上でリソースを投入してください。"
  },
  Summon_117217_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:群星との邂逅·防御型>】運命の軌道連合覚醒において、SSRアイテムを取得する総合確率は100.00%です。取得するSSRアイテムは2つの覚醒体と3つの命輪です。\n·覚醒を通じてSSR覚醒体を取得した場合、100%の確率で<SummonOrange:防御型>の覚醒体となります。\n\n<Title:【特別な説明】>\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回に同じSSR覚醒体を取得した場合、毎回対応する覚醒体の欠片1個と根源の澱50個に変換されます；第17回以降の取得では、非限定SSR覚醒体は「魂の回溯欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「魂の回溯欠片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲・忘却篇など)で取得した覚醒体や溢れた覚醒体の欠片は根源の澱に変換されません。"
  },
  Summon_117217_Name = {
    Text = "運命の軌道連合覚醒"
  },
  Summon_117217_ProbabilityUpDesc = {
    Text = "「防御型」限定覚醒"
