  Summon_117218_Desc = {
    Text = "期間限定イベントで、<SummonOrange:5>回までしか呼び出せない！"
  },
  Summon_117218_LongDesc1 = {
    Text = "【<SummonOrange:群星との邂逅·ダメージ型>】命轨連合覚醒が開放されました。開放期間中、守秘者は1体の星辰篇ダメージ型SSR覚醒体、1体の忘却篇ダメージ型SSR覚醒体、1個の星辰篇ダメージ型覚醒体推薦SSR命輪、2個の忘却篇ダメージ型覚醒体推薦SSR命輪をランダムに覚醒することができます。\n·各運命の軌道連合覚醒は5回の覚醒後に閉じます。\n·今回の運命の軌道連合覚醒イベントでは、毎回の覚醒で必ずランダムSSR覚醒体またはランダムSSR命輪を獲得します。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、覚醒体や命輪の効果が弱体化または強化されるバランス調整が行われることがあります。\n·弱体化が発生した場合、ゲームは期間限定の回溯機能を開放し、覚醒体や命輪の育成または覚醒にリソースを再配置する機会を提供します。\n·このことを理解し、受け入れた上でリソースの投入を行ってください。"
  },
  Summon_117218_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:群星との邂逅·ダメージ型>】運命の軌道連合覚醒において、SSRアイテムの総合取得確率は100.00%です。取得するSSRアイテムは2つの覚醒体と3つの命輪です。\n·覚醒でSSR覚醒体を取得した場合、100%の確率で<SummonOrange:ダメージ型>の覚醒体となります。\n\n<Title:【特別な説明】>\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回目に同じSSR覚醒体を取得した場合、毎回1つの対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回目以降は、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任選方式(原質楽園、灵魂回溯之芯、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体や溢れた覚醒体の欠片を取得した場合、根源の澱には変換されません。"
  },
