  Summon_117219_LongDesc1 = {
    Text = "【<SummonOrange:群星との邂逅·女性>】運命の軌道連合覚醒が開放されました。開放期間中、守秘者は1体の星辰篇女性SSR覚醒体、1体の忘却篇女性SSR覚醒体、1個の星辰篇女性覚醒体推薦SSR命輪、2個の忘却篇女性覚醒体推薦SSR命輪をランダムに覚醒させることができます。\n·各運命の軌道連合覚醒は、5回の覚醒後に終了します。\n·今回の運命の軌道連合覚醒イベントでは、毎回の覚醒で必ずランダムSSR覚醒体またはランダムSSR命輪が獲得できます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保するため、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは限時の回溯機能を開放し、覚醒体や命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解し、受け入れた上でリソースの投入を行ってください。"
  },
  Summon_117219_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:群星との邂逅·女性>】運命の軌道連合覚醒において、SSRアイテムを取得する総合確率は100.00%です。取得されるSSRアイテムは、2体の覚醒体と3つの命輪です。\n·覚醒によってSSR覚醒体を取得した場合、100%の確率で<SummonOrange:女性>の覚醒体となります。\n\n<Title:【特別な説明】>\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回に同じSSR覚醒体を取得した場合、毎回1つの対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降の取得では、非限定SSR覚醒体は「魂の回溯欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「魂の回溯欠片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲・忘却篇など)で覚醒体やオーバーフロー覚醒体の欠片を取得した場合、根源の澱には変換されません。"
  },
