  Summon_117762_Desc = {
    Text = "毎<SummonBlue:5>回の覚醒でSR以上の対象が必ず出現します"
  },
  Summon_117762_LongDesc1 = {
    Text = "【<SummonBlue:深く囚われた願い>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は限時イベントUPキャラクター<SummonBlue:マーフィ>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonBlue:マーフィ>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonBlue:マーフィ>は、初回UP後3ヶ月から9ヶ月の期間限定キャラクターイベント覚醒に出現し、約1年後に【界域研習】常駐キャラクター覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールが発生しない限り、すべての覚醒体または命輪は基本確率を使用し、具体的な内容はルール説明に準じます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に対するリソース再配置の機会を提供するために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_117762_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonBlue:深く囚われた願い>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33%の確率で今期UPのSSR覚醒体<SummonBlue:マーフィー>となります。\n·連続して2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続して{s2}回今期UPキャラクターでないものを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonBlue:深く囚われた願い>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱が副産物として得られます。R命輪を獲得した場合、同時に1個の根源の澱が副産物として得られます。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含む)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます。第17回以降に獲得した場合、非限定SSR覚醒体は【灵魂回溯碎片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【灵魂回溯碎片】×2と【根源の澱】×250に変換されます。ただし、任意の選択方式(原質楽園、返魂のコア、原型視界などを含む)やランダム方式(原質捕獲·忘却篇など)で覚醒体や溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】の保底覚醒回数は共に累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
