  Summon_119592_Title = {
    Text = "銀河が輝くとき"
  },
  Summon_119593_Desc = {
    Text = "<SummonOrange:5>回の覚醒ごとにSR以上確定"
  },
  Summon_119593_LongDesc1 = {
    Text = "【<SummonOrange:絶対的預言者>】期間限定イベントキャラ召喚が開始しました。\n期間中、守秘者は期間限定キャラ<SummonOrange:溶壊・ドール>を召喚で獲得できます。\n\n・期間中、限定SSR覚醒体<SummonOrange:溶壊・ドール>の召喚での出現率が増加します。\n\n・期間終了後も、限定SSR覚醒体<SummonOrange:溶壊・ドール>は最初の登場後、3～9か月の間の期間限定キャラ召喚に再登場し、約1年後に【界域研究】常設キャラ召喚に追加されます。\n\n・今回の期間限定キャラ召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は「召喚ルール」をご参照ください。\n\n・毎日のおすすめ召喚：今回の期間限定キャラ召喚では、守秘者は毎日60プラチナジェルで1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_119593_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonOrange:絶対先知>]期間限定キャライベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて覚醒体で、最大 30 回の覚醒で必ず天井によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33％の確率で今期ピックアップのSSR覚醒体<SummonOrange:メルトダウン·ドール>となります。\n·連続2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラでなかった場合、次回覚醒で獲得するSSRキャラは必ず今期確率アップキャラとなります。{s1}\n·現在連続 {s2} 回、今期ピックアップキャラ以外を獲得しています。{s3}\n\n<Title:[SRアイテム]>\n[<SummonOrange:絶対先知>]キャライベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて運命の輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSR運命の輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R運命の輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を第 2〜16 回獲得した場合、毎回対応する覚醒体の残片 1 個と根源沈殿 50 個に変換されます。第 17 回以降の獲得は、非限定SSR覚醒体の場合、精粋霊核の欠片 1 個、霊核の欠片 3 個と「根源沈殿」× 150に変換されます。限定SSR覚醒体の場合、精粋霊核の欠片 2 個、霊核の欠片 6 個と根源沈殿 250 個に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯の芯、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得、または覚醒体の残片が溢れた場合、根源沈殿は変換されません。\n·今回の覚醒は[キャライベント覚醒]に属し、いずれの[キャライベント覚醒]においても、天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
