  },
  Summon_119603_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:錯位の双生>】期間限定運命の輪イベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて運命の輪であり、最大 30 回の覚醒で天井によりSSR運命の輪を確定入手できます。\n·覚醒でSSR運命の輪を獲得した場合、50.00％の確率で今期ピックアップのSSR運命の輪<SummonOrange:写実主義の逆説>となります。\n·前回の覚醒で獲得したSSR運命の輪が今期確率アップ対象でなかった場合、次回覚醒で獲得するSSR運命の輪は必ず今期確率アップ対象となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:錯位の双生>】運命の輪イベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて運命の輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定入手でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:【特別説明】>\n·覚醒でSSR運命の輪を獲得した際、副産物として根源の沈殿を 50 個同時に獲得します。SR運命の輪を獲得した際は根源の沈殿を 5 個、R運命の輪を獲得した際は根源の沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR運命の輪を第 2〜16 回獲得した場合、毎回自動的に重ね段階がアップし、「根源の沈殿」× 50 を獲得します。第 17 回以降の獲得は「運命遡行の欠片」× 1、「根源の沈殿」× 50、「薔薇金券」× 20000 に変換されます。限定SSR運命の輪は「運命遡行の欠片」× 2、「根源の沈殿」× 50、「薔薇金券」× 20000 に変換されます。ただし、任意選択方式（輪転の書、運命遡行のコア等を含む）およびランダム方式（宿命のスナップ·忘却篇等を含む）で運命の輪を獲得した場合、根源の沈殿への変換は行われません。\n·今回の覚醒は【運命の輪イベント覚醒】に属し、いずれの【運命の輪イベント覚醒】においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n"
  },
  Summon_119603_Name = {
    Text = "イベント運命の札召喚"
  },
  Summon_119603_ProbabilityUpDesc = {
    Text = "<SummonOrange:「写実主義の逆説」>入手確率アップ！"
  },
  Summon_119603_RateListTextR = {
    Text = "R基本出現率：81.12%<color=#A3A6AB>（保証込み総合出現率：69.98%）</color>"
  },
  Summon_119603_RateListTextSR = {
    Text = "SR基本出現率：15.85％<color=#A3A6AB>（保証込み総合出現率：25.00％）</color>"
  },
  Summon_119603_RateListTextSSR = {
    Text = "SSR基本出現率：3.03%<color=#A3A6AB>（保証込み総合出現率：5.02%）</color>"
  },
  Summon_119603_Title = {
    Text = "銀河が輝くとき"
  },
  Summon_119604_Desc = {
    Text = "<SummonOrange:5>回の覚醒ごとにSR以上確定"
  },
  Summon_119604_LongDesc1 = {
    Text = "[<SummonOrange:永遠の炎>]期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UPキャラクター<SummonOrange:ケティグラ>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:ケティグラ>の覚醒獲得確率が上昇します。\n\n·今回の期間限定イベント覚醒では、確率アップや保底などの特殊ルールが発生する場合を除き、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明を基準とします。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60プラチナジェルでお得に1回覚醒でき、さらに60シルバーコアがプレゼントされます。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは期間限定のリセット機能を開放し、覚醒体や命輪の育成または覚醒に再度リソースを配置する機会を提供します。\n·この点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_119604_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonOrange:永燃の火 >]期間限定キャラクターイベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて覚醒体で、最大 30 回の覚醒で天井によりSSR覚醒体を確定入手できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33％の確率で今期ピックアップのSSR覚醒体<SummonOrange:ケティグラ>となります。\n·連続2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでなかった場合、次に覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続 {s2} 回今期ピックアップ以外のキャラクターを獲得しています。{s3}\n\n<Title:[SRアイテム]>\n[<SummonOrange:永燃の火>]キャラクターイベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定入手でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSR命輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を第 2〜16 回獲得した場合、毎回対応する覚醒体の欠片 1 個と根源沈殿 50 個に変換されます。第 17 回以降の獲得では、非限定SSR覚醒体は精粋霊核欠片 1 個、霊核欠片 3 個および「根源沈殿」× 150 に変換され、限定SSR覚醒体は精粋霊核欠片 2 個、霊核欠片 6 個および根源沈殿 250 個に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯の芯、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得、または覚醒体の欠片が溢れた場合、根源沈殿への変換は行われません。\n·今回の覚醒は[キャラクターイベント覚醒]に属し、いずれの[キャラクターイベント覚醒]においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
