  Summon_119607_Title = {
    Text = "銀河が輝くとき"
  },
  Summon_119608_Desc = {
    Text = "<SummonRed:5>回の覚醒ごとにSR以上確定"
  },
  Summon_119608_LongDesc1 = {
    Text = "[<SummonRed:万灵の宴>]期間限定キャラクターイベント覚醒が開始されました。イベント期間中、秘密保持者は期間限定のUPキャラクター<SummonRed:デュレセイン>を覚醒できます。\n・イベント期間中に、限定SSR覚醒体<SummonRed:デュレセイン>の覚醒獲得確率が上昇します。\n\n・今回の期間限定イベント覚醒では、触発確率の上昇や保障などの特別ルールを除き、すべての覚醒体または命輪は基本確率を使用します。具体的な内容は規則説明をご確認ください。\n・毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、秘密保持者は毎日60源液でお得に1回覚醒でき、さらに60シルバーチップが贈呈されます。\n\n<Title:[バランス調整]>\n・ゲームプレイが特別なため、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n・弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再配置のリソースを提供するための限定回溯機能を開放します。\n・必ずこの点を理解し、受け入れた上でリソースの投入を行ってください。\n\n"
  },
  Summon_119608_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonRed:万霊饗宴>]期間限定キャラクターイベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて覚醒体で、最大 30 回の覚醒で天井によりSSR覚醒体を確定入手できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33％の確率で今期ピックアップのSSR覚醒体<SummonRed:デュルセイン>となります。\n·連続2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでなかった場合、次に覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続 {s2} 回今期ピックアップ以外のキャラクターを獲得しています。{s3}\n\n<Title:[SRアイテム]>\n[<SummonRed:万霊饗宴>]キャラクターイベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定入手でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSR命輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を第 2〜16 回獲得した場合、毎回対応する覚醒体の欠片 1 個と根源沈殿 50 個に変換されます。第 17 回以降の獲得では、非限定SSR覚醒体は精粋霊核欠片 1 個、霊核欠片 3 個および「根源沈殿」× 150 に変換され、限定SSR覚醒体は精粋霊核欠片 2 個、霊核欠片 6 個および根源沈殿 250 個に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯の芯、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得、または覚醒体の欠片が溢れた場合、根源沈殿への変換は行われません。\n·今回の覚醒は[キャラクターイベント覚醒]に属し、いずれの[キャラクターイベント覚醒]においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
