  Summon_119621_Title = {
    Text = "銀河が輝くとき"
  },
  Summon_119622_Desc = {
    Text = "<SummonOrange:5>回の召喚ごとにSR以上確定"
  },
  Summon_119622_LongDesc1 = {
    Text = "【<SummonOrange:苦痛の追憶>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UP命輪<SummonOrange:覆い隠された苦痛>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:覆い隠された苦痛>の覚醒獲得確率が上昇します。\n\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的な内容はルール説明に準じます。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドの割引で1回覚醒でき、さらに60シルバーコアを追加でプレゼントします。\n\n<Title:【バランス調整】>\n·ゲームの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再デプロイ資源の機会を提供するために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上で、資源投入を行ってください。\n\n"
  },
  Summon_119622_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:苦痛追憶>】期間限定運命イベント覚醒において、SSRアイテムの獲得基礎確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて運命で、最大 30 回の覚醒で必ず天井によりSSR運命を獲得できます。\n·覚醒でSSR運命を獲得した際、50.00％の確率で今期UP対象のSSR運命<SummonOrange:隠没の痛み>となります。\n·前回の覚醒で獲得したSSR運命が今期確率アップ対象の運命でなかった場合、次回覚醒で獲得するSSR運命は必ず今期確率アップ対象の運命となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:苦痛追憶>】運命イベント覚醒において、SRアイテムの覚醒基礎確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて運命です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:【特別説明】>\n·覚醒でSSR運命を獲得した際、副産物として 50 個の根源沈殿を同時に獲得します。SR運命を獲得した際は 5 個の根源沈殿を、R運命を獲得した際は 1 個の根源沈殿を同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR運命を第 2〜16 回目に獲得した際、毎回自動的に重ね位レベルが上昇し「根源沈殿」× 50を獲得します。第 17 回目以降に獲得した場合は「運命回溯の欠片」× 1、「根源沈殿」× 50、「薔薇金券」× 20000に変換されます。限定SSR運命は「運命回溯の欠片」× 2、「根源沈殿」× 50、「薔薇金券」× 20000に変換されます。ただし、任意選択方式（輪転の書、運命回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で運命を獲得した場合、根源沈殿への変換は行われません。\n·今回の覚醒は【運命イベント覚醒】に属し、いずれの【運命イベント覚醒】においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n"
  },
