  Summon_119630_Desc = {
    Text = "<SummonOrange:5>回の召喚ごとにSR以上確定"
  },
  Summon_119630_LongDesc1 = {
    Text = "【<SummonOrange:死の約束>】期間限定イベント運命の札召喚が開始しました。期間中、守秘者は期間限定の運命の札<SummonOrange:琥珀色の死>を召喚で獲得できます。\n・期間中、限定SSR運命の札<SummonOrange:琥珀色の死>の召喚での出現率が増加します。\n\n・今回の期間限定の運命の札召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は【召喚ルール】をご参照ください。\n・毎日のおすすめ召喚：今回の期間限定の運命の札召喚では、守秘者は毎日60プラチナジェルで1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_119630_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:死の約束>】期間限定運命の輪イベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて運命の輪であり、最大 30 回の覚醒で天井によりSSR運命の輪を確定入手できます。\n·覚醒でSSR運命の輪を獲得した場合、50.00％の確率で今期ピックアップのSSR運命の輪<SummonOrange:琥珀色の死>となります。\n·前回の覚醒で獲得したSSR運命の輪が今期確率アップ対象でなかった場合、次回覚醒で獲得するSSR運命の輪は必ず今期確率アップ対象となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:死の約束>】運命の輪イベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて運命の輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定入手でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:【特別説明】>\n·覚醒でSSR運命の輪を獲得した際、副産物として根源の沈殿を 50 個同時に獲得します。SR運命の輪を獲得した際は根源の沈殿を 5 個、R運命の輪を獲得した際は根源の沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR運命の輪を第 2〜16 回獲得した場合、毎回自動的に重ね段階がアップし、「根源の沈殿」× 50 を獲得します。第 17 回以降の獲得は「運命遡行の欠片」× 1、「根源の沈殿」× 50、「薔薇金券」× 20000 に変換されます。限定SSR運命の輪は「運命遡行の欠片」× 2、「根源の沈殿」× 50、「薔薇金券」× 20000 に変換されます。ただし、任意選択方式（輪転の書、運命遡行のコア等を含む）およびランダム方式（宿命のスナップ·忘却篇等を含む）で運命の輪を獲得した場合、根源の沈殿への変換は行われません。\n·今回の覚醒は【運命の輪イベント覚醒】に属し、いずれの【運命の輪イベント覚醒】においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n"
  },
  Summon_119630_Name = {
    Text = "イベント運命の札召喚"
