  Summon_119634_LongDesc1 = {
    Text = "【<SummonPurple:誘心の医者>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UPキャラクター<SummonPurple:クレメンタイン>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:クレメンタイン>の覚醒取得確率がアップします。\n\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用します。具体的にはルール説明に従ってください。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドの割引で1回覚醒でき、さらに60シルバーコアをプレゼントします。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再展開リソースの機会を提供するために期間限定の回溯機能を開始します。\n·この点を理解し受け入れた上で、リソース投入を行ってください。\n\n"
  },
  Summon_119634_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonPurple:誘心医者>]期間限定キャライベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて覚醒体で、最大 30 回の覚醒で必ず天井によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33％の確率で今期ピックアップのSSR覚醒体<SummonPurple:クレメンティン>となります。\n·連続2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラでなかった場合、次回覚醒で獲得するSSRキャラは必ず今期確率アップキャラとなります。{s1}\n·現在連続 {s2} 回、今期ピックアップキャラ以外を獲得しています。{s3}\n\n<Title:[SRアイテム]>\n[<SummonPurple:誘心医者>]キャライベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて運命の輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSR運命の輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R運命の輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を第 2〜16 回獲得した場合、毎回対応する覚醒体の残片 1 個と根源沈殿 50 個に変換されます。第 17 回以降の獲得は、非限定SSR覚醒体の場合、精粋霊核の欠片 1 個、霊核の欠片 3 個と「根源沈殿」× 150に変換されます。限定SSR覚醒体の場合、精粋霊核の欠片 2 個、霊核の欠片 6 個と根源沈殿 250 個に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯の芯、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得、または覚醒体の残片が溢れた場合、根源沈殿は変換されません。\n·今回の覚醒は[キャライベント覚醒]に属し、いずれの[キャライベント覚醒]においても、天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
