  Summon_119637_LongDesc1 = {
    Text = "[<SummonRed:绘魇狂心>]期間限定のキャラクター活動が開始されました。活動期間中、守秘者は期間限定の活動UPキャラクター<SummonRed:ピクマン>を覚醒できます。\n·活動期間中、限定SSR覚醒体<SummonRed:ピクマン>の覚醒獲得確率が上昇します。\n\n·この期間限定活動の覚醒では、特別ルールを除き、すべての覚醒体や命輪は基本確率が適用され、詳細は規則説明に準じます。\n·毎日のおすすめ覚醒：この期間限定活動の覚醒で、守秘者は毎日60源液で1回の特典覚醒を行え、さらに60銀芯をもらえます。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を保証するために、覚醒体や命輪の効果に対する削弱または強化のバランス調整が行われることがあります。\n·削弱が行われた場合、ゲームは覚醒体や命輪の育成や覚醒においてリソースの再配置を行うチャンスとなる限時回溯機能を開放します。\n·必ずこの点を理解し受け入れた上で、リソースの投入を行ってください。\n\n"
  },
  Summon_119637_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonRed:絵魘狂心>]期間限定キャラクターイベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて覚醒体で、最大 30 回の覚醒で天井によりSSR覚醒体を確定入手できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33％の確率で今期ピックアップのSSR覚醒体<SummonRed:ピックマン>となります。\n·連続2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでなかった場合、次に覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続 {s2} 回今期ピックアップ以外のキャラクターを獲得しています。{s3}\n\n<Title:[SRアイテム]>\n[<SummonRed:絵魘狂心>]キャラクターイベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定入手でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSR命輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を第 2〜16 回獲得した場合、毎回対応する覚醒体の欠片 1 個と根源沈殿 50 個に変換されます。第 17 回以降の獲得では、非限定SSR覚醒体は精粋霊核欠片 1 個、霊核欠片 3 個および「根源沈殿」× 150 に変換され、限定SSR覚醒体は精粋霊核欠片 2 個、霊核欠片 6 個および根源沈殿 250 個に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯の芯、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得、または覚醒体の欠片が溢れた場合、根源沈殿への変換は行われません。\n·今回の覚醒は[キャラクターイベント覚醒]に属し、いずれの[キャラクターイベント覚醒]においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
