  Summon_119659_LongDesc1 = {
    Text = "[<SummonOrange:汚れの付かない花>]期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定イベントUPキャラクター<SummonOrange:リリー>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:リリー>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonOrange:リリー>は初回UP後3〜9ヶ月の期間限定キャラクターイベント覚醒に引き続き登場し、約1年後に[界域研習]常駐キャラクター覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率上昇、保障などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に従います。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、覚醒体や命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再配置リソースの機会を提供するために、期間限定のリセット機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_119659_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:花は塵に染まらず>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保障込み)は5.02%です。獲得したSSRアイテムはすべて覚醒体であり、最大30回の覚醒で必ず保障によりSSR覚醒体を獲得できます。\n·覚醒を通じてSSR覚醒体を獲得した場合、33.33%の確率で今回のUPのSSR覚醒体<SummonOrange:リリー>となります。\n·連続して2回の覚醒で獲得したSSR覚醒体が今回の確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今回の確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回の非今回UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:花は塵に染まらず>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保障込み)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保障によりSR以上のアイテムを獲得でき、保障を通じてSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します。R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は【魂の回溯欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【魂の回溯欠片】×2と【根源の澱】×250に変換されます。ただし、任意選択方式(原質楽園、返魂のコア、精神体カプセルなどを含む)やランダム方式(原質捕獲·忘却篇など)で覚醒体や溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·本覚醒は【キャラクターイベント覚醒】に属し、いかなる【キャラクターイベント覚醒】においても保障覚醒回数は共同で累積され、他の覚醒タイプの保障覚醒回数とは独立して統計されます。\n\n"
