  Summon_119660_RateListTextSSR = {
    Text = "SSR基本出現率：3.03%<color=#A3A6AB>（保証込み総合出現率：5.02%）</color>"
  },
  Summon_119660_Title = {
    Text = "頑固な心"
  },
  Summon_119661_Desc = {
    Text = "<SummonOrange:5>回の召喚ごとにSR以上確定"
  },
  Summon_119661_LongDesc1 = {
    Text = "【<SummonOrange:存続の理>】期間限定の命輪イベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定のUP命輪<SummonOrange:慈悲深き哺育>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:慈悲深き哺育>の覚醒取得確率が上昇します。\n·イベント終了後、限定SSR命輪<SummonOrange:慈悲深き哺育>は初回UP後3〜9ヶ月の期間限定命輪イベント覚醒に引き続き登場し、約1年後に【輪転の相】常駐命輪覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特殊ルールが発生する場合を除き、全ての覚醒体や命輪は基本確率を使用し、具体的なルール説明に従います。\n\n<Title:【バランス調整】>\n·ゲームのプレイスタイル上、ゲームの楽しさと公正性を確保するために、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に資源再配分の機会を提供するために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上で資源を投入してください。\n\n"
  },
  Summon_119661_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:存続の理>】の期間限定命輪イベント覚醒中、SSRアイテムを取得する基本確率は3.03％、総合確率(保底を含む)は5.02％です。取得したSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底によりSSR命輪を取得できます。\n·覚醒でSSR命輪を取得した場合、本期UPのSSR命輪<SummonOrange:慈悲深き哺育>である確率は50.00％です。\n·前回の覚醒で取得したSSR命輪が本期の確率アップ命輪でない場合、次回の覚醒で取得するSSR命輪は必ず本期の確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:存続の理>】の命輪イベント覚醒中、SRアイテムの覚醒の基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97％、SSRアイテムを取得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を取得した際、同時に50個の根源の澱が副産物として得られます；SR命輪を取得した際、同時に5個の根源の澱が副産物として得られます；R命輪を取得した際、同時に1個の根源の澱が副産物として得られます。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回取得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の取得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯のコア等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】内で、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
