  Summon_121425_LongDesc1 = {
    Text = "[<SummonOrange:無界空響>]界域のアンカー唤醒が開始されました。活動期間中、守秘者は忘却篇の<SummonOrange:カオス>界域限定唤醒体とその推奨命輪を唤醒することができます。\n·今回の期間限定活動の唤醒中、触発確率のアップや保底などの特別ルールを除き、すべての唤醒体や命輪は基本確率を使用し、具体的な内容はルール説明に準じます。\n·毎日の推奨唤醒：今回の界域のアンカー唤醒中、守秘者は毎日60源液の特別価格で1回唤醒でき、さらに60銀芯をプレゼントされます。\n\n<Title:[バランス調整]>\n·ゲームのプレイスタイルにより、ゲームの楽しさと公平性を確保するために、唤醒体や命輪の効果に対して弱体化または強化のバランス調整が行われる可能性があります。\n·弱体化が発生した場合、ゲームは唤醒体や命輪の育成または唤醒に対してリソースを再配置する機会を与えるために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上でリソースの投入を行ってください。\n\n"
  },
  Summon_121425_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n·[<SummonOrange:無界空響>]界域アンカー覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムは覚醒体または命輪で、最大 30 回の覚醒で必ず天井によりSSR覚醒体または命輪を獲得できます。\n·覚醒でSSRアイテムを獲得した場合、33.33％の確率でSSR覚醒体となります。\n·連続2回の覚醒で獲得したSSRが命輪だった場合、次に覚醒で獲得するSSRは必ず覚醒体になります。\n·連続2回の覚醒で獲得したSSRが覚醒体だった場合、次に覚醒で獲得するSSRは必ず命輪になります。{s1}\n·現在、連続 {s2} 回SSR覚醒体を獲得しています。{s3}\n·現在、連続 {s4} 回SSR命輪を獲得しています。{s3}\n\n<Title:[SRアイテム]>\n·[<SummonOrange:無界空響>]キャラクター活動覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSSR命輪を獲得した場合、副産物として根源沈殿を 50 個同時に獲得します。覚醒でSR命輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を第 2〜16 回目に獲得した場合、毎回対応する覚醒体の欠片 1 個と根源沈殿 50 個に変換されます。第 17 回目以降に獲得した場合、非限定SSR覚醒体は「魂溯の欠片」× 1 と「根源沈殿」× 150 に変換され、限定SSR覚醒体は「魂溯の欠片」× 2 と「根源沈殿」× 250 に変換されます。ただし、任意選択方式（原質楽園、魂溯のコア、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得した場合、または覚醒体の欠片が溢れた場合は、根源沈殿に変換されません。\n·今回の覚醒は[界域アンカー覚醒]に属し、いずれの[界域アンカー覚醒]においても、天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
