  Summon_121426_LongDesc1 = {
    Text = "[<SummonRed:血脈涓流>]界域のアンカーウェイクが開始されました。活動期間中、守秘者は忘却編の<SummonRed:血肉>界域限定の覚醒体およびその推奨運命の札を呼び出すことができます。\n·今回の期間限定イベントの覚醒中、確率アップや保底などの特別ルールを除き、すべての覚醒体や運命の札は基本確率を使用し、具体的にはルール説明に従います。\n·毎日の推奨覚醒：今回の界域アンカーウェイク中、守秘者は毎日60源液の割引で1回覚醒でき、さらに60銀芯がプレゼントされます。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や運命の札の効果を弱体化または強化するバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や運命の札の育成または覚醒に再配置リソースの機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し受け入れた上で、リソースの投資を行ってください。\n\n"
  },
