  Summon_123144_Desc = {
    Text = "<SummonRed:5>回の覚醒ごとにSR以上確定"
  },
  Summon_123144_LongDesc1 = {
    Text = "[<SummonRed:万霊の饗宴>]期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はその中から期間限定UPキャラクター<SummonRed:ドレセイン>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonRed:ドレセイン>の覚醒獲得確率が上昇します。\n\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールを除いて、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に従います。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、覚醒体や命輪の効果に対して弱体化または強化のバランス調整が行われることがあります。\n·弱体化が発生した場合、ゲームは期間限定の巻き戻し機能を開放し、覚醒体や命輪の育成または覚醒にリソースを再配置する機会を提供します。\n·この点を理解し、受け入れた上でリソースの投入を行ってください。\n\n"
  },
  Summon_123144_LongDesc2 = {
    Text = "<Title:【SSR】>\n【<SummonRed:万霊の饗宴>】期間限定イベントキャラ召喚において、SSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。SSRはすべて覚醒体となり、最大30回の召喚で保証によりSSR覚醒体を必ず獲得できます。\n・召喚でSSR覚醒体を獲得した際、33.33%の確率で今回ピックアップのSSR覚醒体<SummonRed:ドゥルセイン>となります。\n・獲得したSSR覚醒体が2回連続で今回ピックアップのキャラでない場合、次の召喚で獲得するSSRは必ず今回ピックアップのキャラになります。{s1}\n・現在、{s2}回連続で、今回ピックアップのキャラではないものを獲得しています。{s3}\n\n<Title:【SR】>\n【<SummonRed:万霊の饗宴>】キャラ召喚において、SRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。この召喚のSRはすべて運命の札となります。\n・最大5回の召喚で保証によりSR以上を必ず獲得します。保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます。17回目以降は常設（非限定）SSR覚醒体は「魂の回溯欠片」×1と「根源の澱」×150に変換されます。限定SSR覚醒体は「魂の回溯欠片」×2と「根源の澱」×250に変換されます。ただし、任意選択方式（魔封瓶、返魂のコア、精神体カプセルなど）およびランダム方式（根源の捕獲・忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は、「根源の澱」には変換されません。\n・この召喚タイプは【イベントキャラ召喚】に該当します。どの【イベントキャラ召喚】でも保証召喚回数は共通して累積されます。他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n\n"
  },
