  Summon_124043_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:トゲの主>】限定キャラクターイベント覚醒中にSSRアイテムを獲得する基本確率は3.03％、総合確率(保底を含む)は5.02％です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒を通じてSSR覚醒体を獲得した場合、33.33％の確率で今期UPのSSR覚醒体<SummonPurple:ワンダ>となります。\n·連続して2回覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回の非今期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonPurple:トゲの主>】キャラクターイベント覚醒中にSRアイテムを獲得する基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した際、5個の根源の澱を副産物として同時に獲得します；R命輪を獲得した際、1個の根源の澱を副産物として同時に獲得します。\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含む)であっても、第2〜16回に同じSSR覚醒体を獲得した際は、毎回対応する覚醒体の欠片1個と根源の澱50個に変換されます；第17回以降の獲得では、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、いずれの【キャラクターイベント覚醒】においても、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
