  Summon_124045_Title = {
    Text = "神国の諭令"
  },
  Summon_124046_Desc = {
    Text = "<SummonPurple:5>回の召喚ごとにSR以上確定"
  },
  Summon_124046_LongDesc1 = {
    Text = "[<SummonPurple:縦声饗宴>]期間限定命輪イベント覚醒が開催中です。イベント期間中、秘密の守り人は期間限定イベントUP命輪<SummonPurple:女王の戒律>を覚醒から獲得できます。\n·イベント期間中、限定SSR命輪<SummonPurple:女王の戒律>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップ・天井等の特殊ルールの発動を除き、すべての覚醒体または命輪は基礎確率が適用されます。詳細はルール説明をご確認ください。\n\n<Title:[バランス調整]>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは期間限定の遡行機能を開放し、覚醒体・命輪の育成または覚醒に対してリソースを再配置する機会を提供します。\n·この点をご理解・ご了承いただいた上で、リソースの投入をお願いいたします。\n\n"
  },
  Summon_124046_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonPurple:縦声饗宴>]期間限定命輪イベント覚醒において、SSRアイテムの基礎確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて命輪であり、最大 30 回の覚醒で天井によりSSR命輪を確定で獲得できます。\n·覚醒でSSR命輪を獲得した場合、50.00％の確率で今期ピックアップのSSR命輪<SummonPurple:女王の戒律>となります。\n·前回の覚醒で獲得したSSR命輪が今期確率アップ命輪でなかった場合、次に覚醒で獲得するSSR命輪は必ず今期確率アップ命輪となります。\n\n<Title:[SRアイテム]>\n[<SummonPurple:縦声饗宴>]命輪イベント覚醒において、SRアイテムの基礎確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定で獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSSR命輪を獲得した場合、副産物として根源沈殿を 50 個同時に獲得します。SR命輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム配布等を含むがこれに限らない）であっても、同一のSSR命輪を第 2〜16 回獲得した場合、毎回自動的に重ね段階がアップし、【根源沈殿】×50を獲得します。第 17 回以降の獲得は【命途遡行欠片】× 1、【根源沈殿】× 50、【薔薇金券】× 20000に変換されます。限定SSR命輪は【命途遡行欠片】× 2、【根源沈殿】× 50、【薔薇金券】× 20000に変換されます。ただし、任意選択方式（輪転の書、命途遡行のコア等を含む）およびランダム方式（宿命キャプチャ·忘却篇等を含む）で命輪を獲得した場合、根源沈殿への変換は行われません。\n·今回の覚醒は[命輪イベント覚醒]に属し、いずれの[命輪イベント覚醒]においても、天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n"
  },
