    Text = "[<SummonBlue:深淵降誕>]期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定UPキャラクター<SummonBlue:ミリアム>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonBlue:ミリアム>の覚醒獲得確率が上昇します。\n·今回の期間限定イベント覚醒では、確率上昇や保障などの特別なルールを除き、すべての覚醒体や命輪は基本確率が適用され、具体的にはルール説明に従います。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは期間限定の巻き戻し機能を開放し、覚醒体や命輪の育成や覚醒に再度リソースを再配置する機会を提供します。\n·必ずこのことを理解し、受け入れた上でリソースを投入してください。\n\n"
