  Summon_124047_Title = {
    Text = "深淵降誕"
  },
  Summon_124974_Desc = {
    Text = "<SummonOrange:5>回の覚醒ごとにSR以上確定"
  },
  Summon_124974_LongDesc1 = {
    Text = "[<SummonOrange:亦如本我>]期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定UPキャラクター<SummonOrange:「24」>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:「24」>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールが発動しない限り、すべての覚醒体や命輪は基本確率が適用され、具体的な内容はルール説明に準じます。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するため、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは期間限定の回溯機能を開放し、覚醒体や命輪の育成または覚醒にリソースを再配置する機会を提供します。\n·このことを理解し、受け入れた上でリソースの投入を行ってください。\n\n"
  },
  Summon_124974_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:亦如本我>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムは全て覚醒体であり、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33%の確率で今期UPのSSR覚醒体<SummonOrange:「24」>になります。\n·連続して2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターになります。{s1}\n·現在、連続{s2}回非今期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:亦如本我>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。この覚醒内のSRアイテムは全て命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底によりSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱が副産物として獲得されます；R命輪を獲得した場合、同時に1個の根源の澱が副産物として獲得されます。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含む)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は【魂溯の欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【魂溯の欠片】×2と【根源の澱】×250に変換されます。しかし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、いかなる【キャラクターイベント覚醒】においても保底覚醒回数は共に累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
