  },
  Summon_129492_LongDesc1 = {
    Text = "[<SummonOrange:万千の遥望の中で>]期間限定イベントの覚醒が開始されました。イベント期間中、守秘者は<SummonOrange:自由選定>の混沌界域の覚醒体と推奨命輪の取得確率がアップします。\n\n·イベント期間中、選定された<SummonOrange:SSR覚醒体と推奨命輪>の覚醒取得確率が上昇します。\n·今回の期間限定イベントの覚醒では、確率上昇や保障などの特別ルールが発生しない限り、すべての覚醒体または命輪は基本確率を使用し、具体的な内容はルール説明に準じます。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは期間限定の巻き戻し機能を開放し、覚醒体や命輪の育成または覚醒にリソースを再配置する機会を提供します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_129492_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonOrange:万千の遥望の中で>]期間限定イベント覚醒において、SSRアイテムの基礎確率は3.03％、総合確率（天井含む）は5.02％です。獲得できるSSRアイテムは覚醒体または命輪で、最大30回の覚醒で必ず天井によりSSR覚醒体またはおすすめ命輪を獲得できます。\n·覚醒によりSSRを獲得した場合、33.33％の確率で今期選定のSSR<SummonOrange:覚醒体またはおすすめ命輪>となります。\n·今回の覚醒で獲得したSSRが今期選定のSSR覚醒体または命輪でない場合、次回覚醒で獲得するSSRは必ず今期選定のSSR覚醒体または命輪となります。{s1}\n·現在、連続{s2}回今期選定外の覚醒体または命輪を獲得しています。{s3}\n·連続2回の覚醒で同じ今期UPアイテムを獲得した場合、次回覚醒で獲得するUPは必ずもう一方の今期UPアイテムとなります。\n·現在、連続{s4}回今期UP覚醒体を獲得しています。\n·現在、連続{s5}回今期UP命輪を獲得しています。\n\n<Title:[SRアイテム]>\n[<SummonOrange:万千の遥望の中で>]イベント覚醒において、SRアイテムの基礎確率は15.85％、総合確率（天井含む）は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSSR命輪を獲得した場合、副産物として根源沈殿50個を同時に獲得します。覚醒でSR命輪を獲得した場合、副産物として根源沈殿5個を同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿1個を同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の欠片1個と根源沈殿50個に変換されます。17回目以降に獲得した場合、非限定SSR覚醒体は「魂溯の欠片」×1と「根源沈殿」×150に変換され、限定SSR覚醒体は「魂溯の欠片」×2と「根源沈殿」×250に変換されます。ただし、任意選択方式（原質楽園、魂溯のコア、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得、または覚醒体の欠片が溢れた場合、根源沈殿への変換は行われません。\n·今回の覚醒は[循序命理]に属します。いずれの[循序命理]においても、天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
