  Summon_129494_Title = {
    Text = "無数の遠くを見つめて"
  },
  Summon_129495_Desc = {
    Text = "同一のピックアップの取得は連続<{s1}:2>回まで"
  },
  Summon_129495_LongDesc1 = {
    Text = "[<SummonBlue:万千の遥望の中で>]期間限定イベントの覚醒が開始されました。イベント期間中、守秘者は<SummonBlue:自由に選定>深海界域の覚醒体と推薦命輪の取得確率がアップします。\n\n·イベント期間中に選定された<SummonBlue:SSR覚醒体と推薦命輪>の覚醒取得確率が向上します。\n·今回の期間限定イベントの覚醒では、確率アップや保底などの特別ルールが発生する場合を除き、すべての覚醒体や命輪は基本確率が適用され、具体的にはルール説明に従います。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性により、ゲームの楽しさと公平性を確保するために、覚醒体や命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再配置リソースの機会を提供するために期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上で、リソースの投入を行ってください。\n\n"
  },
