  },
  Summon_129497_LongDesc1 = {
    Text = "[<SummonOrange:時系列外同行·星辰篇男性>]運命の軌道連合覚醒が開始されました。開始期間中、守秘者はランダムに2つの星辰篇男性SSR覚醒体、3つの星辰篇男性覚醒体推薦SSR命輪を覚醒することができます。\n·各運命の軌道連合覚醒は5回の覚醒後に終了します。\n·今回の運命の軌道連合覚醒イベントでは、毎回の覚醒で必ずランダムSSR覚醒体またはランダムSSR命輪が獲得できます。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性により、ゲームの楽しさと公平性を確保するために、覚醒体や命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは限時の回溯機能を開放し、覚醒体や命輪の育成または覚醒にリソースを再配置する機会を提供します。\n·この点を理解し、受け入れた上でリソースの投入を行ってください。"
  },
  Summon_129497_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonOrange:時序外同行·星辰篇男性>]運命軌道合契覚醒において、SSRアイテムの総合確率は100.00％です。獲得できるSSRアイテムは覚醒体2個と命輪3個です。\n·覚醒によりSSR覚醒体を獲得した場合、100％の確率で星辰篇<SummonOrange:男性>の覚醒体となります。\n\n<Title:[特別説明]>\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の欠片1個と根源沈殿50個に変換されます。17回目以降に獲得した場合、非限定SSR覚醒体は「魂溯の欠片」×1と「根源沈殿」×150に変換され、限定SSR覚醒体は「魂溯の欠片」×2と「根源沈殿」×250に変換されます。ただし、任意選択方式（原質楽園、魂溯のコア、原型視界等を含む）およびランダム方式（原質捕獲·星辰篇等を含む）で覚醒体を獲得、または覚醒体の欠片が溢れた場合、根源沈殿への変換は行われません。"
  },
