  Summon_130227_LongDesc1 = {
    Text = "【<SummonRed:愛と死の芽>】期間限定イベントキャラ召喚が開始しました。期間中、守秘者は期間限定キャラ<SummonRed:沙耶>を召喚で獲得できます。\n·期間中、限定SSR覚醒体<SummonRed:沙耶>の召喚での出現率が増加します。\n·今回の期間限定キャラ召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は「召喚ルール」をご参照ください。\n·毎日のおすすめ召喚：今回の期間限定キャラ召喚では、守秘者は毎日60プラチナジェルで1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【バランス調整】>\n·ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n·効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n·以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n<Title:【特記事項】>\n·<SummonRed:沙耶>は「沙耶の唄」特別コラボ覚醒体です（<SummonRed:世界が芳しくなりますように>は「沙耶の唄」コラボ運命の札）。初回登場後、比較的長いライセンス期間を有しており、ライセンス期間中に複数回復刻される可能性があり、他の方法でも獲得できます。ライセンス期間満了が近づき、諸般の事情により継続が困難な場合は、事前に告知いたします。\n\n"
  },
  Summon_130227_LongDesc2 = {
    Text = "<Title:【SSR】>\n【<SummonRed:愛と死の芽>】期間限定イベントキャラ召喚において、SSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。SSRはすべて覚醒体となり、最大30回の召喚で保証によりSSR覚醒体を必ず獲得できます。\n·召喚でSSR覚醒体を獲得した際、33.33%の確率で今回ピックアップのSSR覚醒体<SummonRed:沙耶>となります。\n·獲得したSSR覚醒体が2回連続で今回ピックアップのキャラでない場合、次の召喚で獲得するSSRは必ず今回ピックアップのキャラになります。{s1}\n·現在、{s2}回連続で、今回ピックアップのキャラではないものを獲得しています。{s3}\n\n<Title:【SR】>\n【<SummonRed:愛と死の芽>】キャラ召喚において、SRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。この召喚のSRはすべて運命の札となります。\n·最大5回の召喚で保証によりSR以上を必ず獲得します。保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n·SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n·いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます。17回目以降は常設（非限定）SSR覚醒体は「魂の回溯の欠片」×1と「根源の澱」×150に変換されます。限定SSR覚醒体は「魂の回溯の欠片」×2と「根源の澱」×250に変換されます。ただし、任意選択方式（魔封瓶、返魂のコア、精神体カプセルなど）およびランダム方式（根源の捕獲·忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は、「根源の澱」には変換されません。\n·この召喚タイプは【イベントキャラ召喚】に該当します。どの【イベントキャラ召喚】でも保証召喚回数は共通して累積されます。他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n\n"
  },
