  Summon_130227_Title = {
    Text = "愛と死の芽"
  },
  Summon_130228_Desc = {
    Text = "<SummonRed:5>回の召喚ごとにSR以上確定"
  },
  Summon_130228_LongDesc1 = {
    Text = "【<SummonRed:heterogeneous feather species>】期間限定命輪イベント覚醒が開始しました。期間中、守秘者は期間限定イベントUP命輪<SummonRed:花香る世界を願って>を覚醒で獲得できます。\n·期間中、限定SSR命輪<SummonRed:花香る世界を願って>の覚醒での出現率が増加します。\n·今回の期間限定覚醒では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や命輪は基本確率で取得できます。詳細はルール説明をご参照ください。\n·毎日のおすすめ覚醒：今回の期間限定覚醒では、守秘者は毎日60プラチナジェルで1回覚醒でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【バランス調整】>\n·ゲームの特性上、ゲームの楽しさと公平性を確保するため、覚醒体や命輪の効果を弱化または強化するバランス調整を行う場合があります。\n·効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や命輪の育成や覚醒に必要なリソースを再分配する機会を提供します。\n·以上の点をご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n<Title:【特別説明】>\n·<SummonRed:沙耶>は【沙耶の歌】特別コラボ覚醒体（<SummonRed:花香る世界を願って>は【沙耶の歌】コラボ命輪）であり、初回登場後は比較的長いライセンス期間を持ち、期間中に複数回復刻される可能性があり、他の方法でも入手できます。ライセンス期間満了前に、諸般の事情により継続が困難な場合は、事前にお知らせします。"
  },
  Summon_130228_LongDesc2 = {
    Text = "<Title:【SSR】>\n・【<SummonRed:異界の種子の羽>】期間限定イベント運命の札召喚において、\nSSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。\nSSRはすべて運命の札となり、最大30回の召喚で保証によりSSR運命の札を必ず獲得できます。\n・召喚でSSR運命の札を獲得した際、50.00%の確率で今回ピックアップのSSR運命の札<SummonRed:花香る世界を願って>となります。\n・前回獲得したSSR運命の札が今回の確率アップ対象でない場合、次の召喚で獲得するSSR運命の札は必ず今回の確率アップ対象の運命の札になります。\n\n<Title:【SR】>\n・【<SummonRed:異界の種子の羽>】運命の札召喚において、\nSRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。\nこの召喚のSRはすべて運命の札となります。\n\n・最大5回の召喚で保証によりSR以上を必ず獲得します。\n保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SSR運命の札を獲得すると、同時に50個の「根源の澱」を副産物として獲得します。\n・SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。\n・R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いかなる方法（召喚、ショップ交換、システム配布等を含むがこれに限らない）であっても、同一のSSR運命の札を2〜16回目に獲得した場合、毎回自動的に重ね段階がアップし「根源の澱」×50を獲得します。17回目以降の獲得は「運命回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR運命の札は「運命回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、運命回溯のコア等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で運命の札を獲得した場合、根源の澱への変換は行われません。\n・この召喚タイプは【イベント運命の札召喚】に該当します。\nどの【イベント運命の札召喚】でも保証召喚回数は共通して累積されます。\n他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n"
  },
