  Summon_130359_LongDesc1 = {
    Text = "[<SummonOrange:一時的なテキスト>]期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UP命輪<SummonOrange:サトグア専用武器>を覚醒できます。\n·イベント期間中、限定SSR命輪<SummonOrange:サトグア専用武器>の覚醒獲得確率が上昇します。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールが発生する場合を除き、すべての覚醒体または命輪は基本確率を使用し、具体的にはルール説明に準じます。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60プラチナジェルの割引で1回覚醒でき、さらに60シルバーコアを追加で贈呈します。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行う可能性があります。\n·弱体化が発生した場合、ゲームは期間限定のリセット機能を開放し、覚醒体や命輪の育成や覚醒に再度リソースを再配置する機会を提供します。\n·この点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_130359_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n[<SummonOrange:仮テキスト>]期間限定命輪イベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得できるSSRアイテムはすべて命輪で、最大 30 回の覚醒で天井によりSSR命輪を確定で獲得できます。\n·覚醒でSSR命輪を獲得した場合、50.00％の確率で今期PUのSSR命輪<SummonOrange:ツァトゥグァ専用武器>となります。\n·前回の覚醒で獲得したSSR命輪が今期確率UP命輪でなかった場合、次回覚醒で獲得するSSR命輪は必ず今期確率UP命輪となります。\n\n<Title:[SRアイテム]>\n[<SummonOrange:仮テキスト>]命輪イベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定で獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSSR命輪を獲得した場合、副産物として根源の沈殿を 50 個同時に獲得します。SR命輪を獲得した場合、副産物として根源の沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源の沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第 2〜16 回獲得した場合、毎回自動的に重ねランクが上昇し、【根源の沈殿】×50を獲得します。第 17 回以降に獲得した場合、【運命遡行の欠片】× 1、【根源の沈殿】× 50、【薔薇金券】× 20000に変換されます。限定SSR命輪は【運命遡行の欠片】× 2、【根源の沈殿】× 50、【薔薇金券】× 20000に変換されます。ただし、任意選択方式（輪転の書、運命遡行のコア等を含む）およびランダム方式（宿命カット·忘却篇等を含む）で命輪を獲得した場合、根源の沈殿への変換は行われません。\n·今回の覚醒は[命輪イベント覚醒]に属し、いずれの[命輪イベント覚醒]においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n"
  },
