  Summon_130361_LongDesc1 = {
    Text = "【<SummonOrange:一時的テキスト>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUPキャラクター<SummonOrange:サトグア>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:サトグア>の覚醒取得確率が上昇します。\n·今回の期間限定イベント覚醒では、確率上昇・天井などの特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60プラチナジェルの特別価格で1回覚醒でき、さらに60シルバーコアが追加でプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対してナーフまたはバフのバランス調整を行う場合があります。\n·ナーフが発生した場合、ゲームは期間限定リセット機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点をご理解・ご了承の上で、リソースを投入してください。"
  },
  Summon_130361_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:一時的テキスト>】期間限定キャラクターイベント覚醒において、SSRアイテムを取得する基礎確率は 3.03%、総合確率（天井含む）は 5.02% です。取得できるSSRアイテムはすべて覚醒体であり、最大 30 回の覚醒で必ず天井によりSSR覚醒体を取得できます。\n·覚醒によってSSR覚醒体を取得した際、33.33% の確率で今期UPのSSR覚醒体<SummonOrange:サトグア>となります。\n·連続2回の覚醒で取得したSSR覚醒体が今期確率上昇キャラクターでない場合、次回覚醒で取得するSSRキャラクターは必ず今期確率上昇キャラクターとなります。{s1}\n·現在、連続 {s2} 回今期UPキャラクター以外を取得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:一時的テキスト>】キャラクターイベント覚醒において、SRアイテムを取得する基礎確率は 15.85%、総合確率（天井含む）は 25.00% です。この覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを取得でき、天井によりSRアイテムを取得する確率は 96.97%、SSRアイテムを取得する確率は 3.03% です。\n\n<Title:【特別説明】>\n·覚醒でSR命輪を取得した際、副産物として 5 個の根源の澱を同時に取得します；R命輪を取得した際、副産物として 1 個の根源の澱を同時に取得します。\n·いかなる方法（覚醒・ショップ交換・システム贈呈等を含むがこれに限らない）によらず、同一のSSR覚醒体を 2〜16 回目に取得した場合、毎回対応する覚醒体の欠片 1 個と根源の澱 50 個に変換されます；17 回目以降に取得した場合、非限定SSR覚醒体は「ソウルリセットの破片」× 1 と「根源の澱」× 150 に変換され、限定SSR覚醒体は「ソウルリセットの破片」× 2 と「根源の澱」× 250 に変換されます。ただし、任意選択方式（魔封瓶・返魂のコア・精神体カプセル等を含む）およびランダム方式（セフィロトキャプチャ·忘却篇等を含む）によって覚醒体または覚醒体の欠片を超過取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【キャラクターイベント覚醒】に属します。任意の【キャラクターイベント覚醒】において、天井の覚醒回数は共通で累計され、他の覚醒タイプの天井回数とは独立して集計されます。"
  },
