  Summon_131639_LongDesc1 = {
    Text = "【<SummonOrange:暗夜の灯火>】キャラ選択召喚・期間限定召喚が開始されました。イベント期間中、守秘者は<SummonOrange:自由に選択>した指定数の覚醒体の出現率がアップします。\n\n・期間中、選択した覚醒体の召喚での出現率がアップします。\n・今回のキャラ選択召喚・期間限定召喚では、確率増加や保証などの特別ルールを除き、すべての覚醒体または運命の札は基本確率で取得できます。詳細は「召喚ルール」をご参照ください。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n"
  },
  Summon_131639_LongDesc2 = {
    Text = "<Title:【SSR】>\n・【<SummonOrange:暗夜の灯火>】キャラ選択召喚・期間限定召喚において、\nSSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。\nSSRはすべて覚醒体となり、最大30回の召喚で保証によりSSR覚醒体を必ず獲得できます。\n・SSRを獲得した際、50%の確率で今回選択したSSR<SummonOrange:覚醒体>が出現します。\n・今回の召喚で取得したSSRが選択したSSR覚醒体でない場合、次回の召喚で取得するSSRは必ず選択したSSR覚醒体となります。{s1}\n・現在、{s2}回連続で、今回選択した覚醒体ではないものを獲得しています。{s3}\n\n<Title:【SR】>\n・【<SummonOrange:暗夜の灯火>】キャラ選択召喚・期間限定召喚において、\nSRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。\nこの召喚のSRはすべて運命の札となります。\n\n・最大5回の召喚で保証によりSR以上を必ず獲得します。\n保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます。17回目以降は、非限定SSR覚醒体は「返魂の欠片」×1と「根源の澱」×150に、限定SSR覚醒体は「返魂の欠片」×2と「根源の澱」×250に変換されます。ただし、任意選択方式（魔封瓶、返魂のコア、精神体カプセルなど）およびアイテム消費によるランダム獲得方式（根源の捕獲・忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は「根源の澱」には変換されません。\n・この召喚タイプは【キャラ選択召喚】に該当します。どの【キャラ選択召喚】でも保証召喚回数は共通して累積され、他の召喚タイプとは別個にカウントされます。"
  },
  Summon_131639_Name = {
    Text = "キャラ選択召喚"
