  Summon_132327_Desc = {
    Text = "<SummonRed:5>回の覚醒ごとにSR以上確定"
  },
  Summon_132327_LongDesc1 = {
    Text = "[<SummonRed:高杯の盛筵>]期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUPキャラクター<SummonRed:ソレール>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonRed:ソレール>の覚醒獲得確率が上昇します。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に従います。\n\n<Title:[バランス調整]>\n·ゲームプレイの特性により、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒のためにリソースを再配置する機会を提供する期間限定リセット機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_132327_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonRed:高杯の盛筵>】限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03％、総合確率(保底を含む)は5.02％です。獲得したSSRアイテムはすべて覚醒体であり、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33％の確率で今期UPのSSR覚醒体<SummonRed:索蕾尔>となります。\n·連続して2回覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、すでに連続{s2}回非今期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonRed:高杯の盛筵>】キャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·どのような方法(覚醒、商店交換、システム贈呈などを含む)であっても、第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、精神体カプセルなどを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
