  Summon_133266_LongDesc1 = {
    Text = "[<SummonOrange:千幕遊記·忘却篇>]衆生百相覚醒が開催中です。イベント期間中、守秘者はすべての忘却篇の限定覚醒体と限定命輪を覚醒から獲得できます。\n·今回の期間限定イベント覚醒では、確率アップや天井などの特殊ルールの発動を除き、すべての覚醒体または命輪は基礎確率が適用されます。詳細はルール説明をご確認ください。\n·毎日おすすめ覚醒：今回の衆生百相覚醒では、守秘者は毎日60源液のお得な価格で1回覚醒でき、さらに60銀芯が追加で贈呈されます。\n\n<Title:[バランス調整]>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体や命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは期間限定の回溯機能を開放し、覚醒体や命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点をご理解・ご了承いただいた上で、リソースの投入を行ってください。\n\n"
  },
  Summon_133266_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n·[<SummonOrange:千幕遊記·忘却篇>]衆生百相覚醒において、SSRアイテムの基礎確率は3.03％、総合確率（天井含む）は5.02％です。獲得できるSSRアイテムは覚醒体または命輪で、最大30回の覚醒で必ず天井によりSSR覚醒体または命輪を獲得できます。\n·覚醒によりSSRアイテムを獲得した場合、33.33％の確率でSSR覚醒体となります。\n·連続2回の覚醒で獲得したSSRが命輪だった場合、次回覚醒で獲得するSSRは必ず覚醒体となります。\n·連続2回の覚醒で獲得したSSRが覚醒体だった場合、次回覚醒で獲得するSSRは必ず命輪となります。{s1}\n·現在、連続{s2}回SSR覚醒体を獲得しています。{s3}\n·現在、連続{s4}回SSR命輪を獲得しています。{s3}\n\n<Title:[SRアイテム]>\n·[<SummonOrange:千幕遊記·忘却篇>]キャラクターイベント覚醒において、SRアイテムの基礎確率は15.85％、総合確率（天井含む）は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSSR命輪を獲得した場合、副産物として根源沈殿50個を同時に獲得します。覚醒でSR命輪を獲得した場合、副産物として根源沈殿5個を同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿1個を同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を2〜16回目に獲得した場合、毎回自動的に重ね掛けランクがアップし、「根源沈殿」×50を獲得します。17回目以降に獲得した場合、「命途回溯の欠片」×1、「根源沈殿」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源沈殿」×50、「薔薇金券」×20000に変換されます。同一のSSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の欠片1個と根源沈殿50個に変換されます。17回目以降に獲得した場合、非限定SSR覚醒体は「魂溯の欠片」×1と「根源沈殿」×150に変換され、限定SSR覚醒体は「魂溯の欠片」×2と「根源沈殿」×250に変換されます。ただし、任意選択方式（原質楽園、魂溯のコア、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得、または覚醒体の欠片が溢れた場合、根源沈殿への変換は行われません。\n·今回の覚醒は[衆生百相覚醒]に属します。いずれの[衆生百相覚醒]においても、天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
