  Summon_138790_LongDesc1 = {
    Text = "【<SummonOrange:群星の盛華·ダメージ型>】命軌合契·三倍覚醒が開催中。開催期間中、秘密の守り人はここからランダムで6体のダメージ型SSR覚醒体、9個のダメージ型覚醒体推奨SSR命輪を覚醒できます。\n·各命軌合契·三倍覚醒は覚醒5回後に終了します。\n·今回の命軌合契·三倍覚醒イベントでは、毎回の覚醒で必ずランダムSSR覚醒体またはランダムSSR命輪を獲得できます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲーム内で期間限定の回溯機能が開放され、覚醒体・命輪の育成や覚醒に投入したリソースを再配置する機会が提供されます。\n·この点をご理解・ご了承の上で、リソースの投入をお願いいたします。"
  },
  Summon_138790_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:群星の盛華·ダメージ型>】命軌合契·三倍覚醒において、SSRアイテムの獲得総合確率は100.00％です。獲得できるSSRアイテムは6体の覚醒体と9個の命輪です。\n·覚醒でSSR覚醒体を獲得した場合、100％の確率で<SummonOrange:ダメージ型>の覚醒体となります。\n\n<Title:【特別説明】>\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の欠片1個と根源沈殿50個に変換されます。17回目以降に獲得した場合、非限定SSR覚醒体は「魂魄回溯の欠片」×1と「根源沈殿」×150に変換され、限定SSR覚醒体は「魂魄回溯の欠片」×2と「根源沈殿」×250に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯のコア、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得した場合、または覚醒体の欠片が溢れた場合は、根源沈殿への変換は行われません。"
  },
