  },
  Summon_138829_LongDesc1 = {
    Text = "【<SummonPurple:宿願の残響>】縛誓の諭が開催中。イベント期間中、秘密の守り人はここから期間限定イベントUPキャラクター<SummonPurple:ダフォディル>と期間限定UP命輪<SummonPurple:「至高の珍蔵品」>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:ダフォディル>と限定SSR命輪<SummonPurple:「至高の珍蔵品」>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップ・天井等の特殊ルール発動時を除き、すべての覚醒体または命輪は基礎確率が適用されます。詳細はルール説明をご確認ください。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲーム内で期間限定の回溯機能が開放され、覚醒体・命輪の育成や覚醒に投入したリソースを再配置する機会が提供されます。\n·この点をご理解・ご了承の上で、リソースの投入をお願いいたします。\n\n"
  },
  Summon_138829_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:宿願の残響>】縛誓の諭において、SSRアイテムの獲得基礎確率は3.03％、総合確率（天井含む）は5.02％です。獲得できるSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず天井によりSSR覚醒体またはSSR命輪を獲得できます。\n·覚醒でSSRを獲得した場合、33.33％の確率で今期UPのSSR覚醒体<SummonPurple:ダフォディル>とSSR命輪<SummonPurple:「至高の珍蔵品」>となります。\n·今回の覚醒で獲得したSSRが今期指定のSSR覚醒体または命輪でなかった場合、次回覚醒で獲得するSSRは必ず今期指定のSSR覚醒体または命輪となります。{s1}\n·現在、今期指定外の覚醒体または命輪を連続 {s2} 回獲得しています。{s3}\n·連続2回同じ今期UPアイテムを覚醒で獲得した場合、次回覚醒で獲得するUPは必ずもう一方の今期UPアイテムとなります。\n·現在、今期UP覚醒体を連続 {s4} 回獲得しています。\n·現在、今期UP命輪を連続 {s5} 回獲得しています。\n\n<Title:【SRアイテム】>\n【<SummonPurple:宿願の残響>】イベント覚醒において、SRアイテムの獲得基礎確率は15.85％、総合確率（天井含む）は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別説明】>\n·覚醒でSSR命輪を獲得した場合、同時に根源沈殿50個が副産物として獲得されます。SR命輪を獲得した場合は根源沈殿5個、R命輪を獲得した場合は根源沈殿1個が副産物として獲得されます。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を2〜16回目に獲得した場合、毎回自動的に重ねランクが上昇し「根源沈殿」×50を獲得します。17回目以降に獲得した場合、「命途回溯の欠片」×1、「根源沈殿」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源沈殿」×50、「薔薇金券」×20000に変換されます。同一のSSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の欠片1個と根源沈殿50個に変換されます。17回目以降に獲得した場合、非限定SSR覚醒体は「魂魄回溯の欠片」×1と「根源沈殿」×150に変換され、限定SSR覚醒体は「魂魄回溯の欠片」×2と「根源沈殿」×250に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯のコア、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得した場合、または覚醒体の欠片が溢れた場合は、根源沈殿への変換は行われません。\n·今回の覚醒は【縛誓の諭】に属します。いずれの【縛誓の諭】においても、天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
