  Summon_138836_LongDesc1 = {
    Text = "【<SummonOrange:宿願の残響>】縛誓の諭が開放されました。イベント期間中、秘密保持者は期間限定イベントUPキャラクター<SummonOrange:リリー>と期間限定UP命輪<SummonOrange:「痛みを越えて」>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:リリー>と限定SSR命輪<SummonOrange:「痛みを越えて」>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップ・天井などの特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率が適用されます。詳細はルール説明をご確認ください。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは期間限定の遡行機能を開放し、覚醒体・命輪の育成または覚醒に対してリソースを再配置する機会を提供します。\n·この点をご理解・ご了承いただいた上で、リソースの投入を行ってください。"
  },
