  Summon_138847_Desc = {
    Text = "同じUPアイテムを連続で最大<SummonOrange:2>回獲得できます！"
  },
  Summon_138847_LongDesc1 = {
    Text = "【<SummonOrange:宿願の残響>】縛誓の諭が開催中です。イベント期間中、秘密の守り人は期間限定イベントUPキャラクター<SummonOrange:モシャ>および期間限定UP命輪<SummonOrange:「狂戮、世界の果てまで」>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:モシャ>および限定SSR命輪<SummonOrange:「狂戮、世界の果てまで」>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップ・天井等の特殊ルール発動時を除き、すべての覚醒体または命輪は基礎確率が適用されます。詳細はルール説明をご確認ください。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲーム内で期間限定の遡行機能が開放され、覚醒体・命輪の育成や覚醒に投入したリソースを再配置する機会が提供されます。\n·この点をご理解・ご了承の上で、リソースの投入を行ってください。\n\n"
  },
