  Summon_138853_Desc = {
    Text = "同じUPアイテムを連続で最大<SummonPurple:2>回獲得できます！"
  },
  Summon_138853_LongDesc1 = {
    Text = "【<SummonPurple:宿願の残響>】縛誓の諭が開催中です。イベント期間中、秘密の守り手は期間限定UP対象キャラクター<SummonPurple:ポリュクス>および期間限定UP命輪<SummonPurple:「歪みし騎士の詩」>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:ポリュクス>および限定SSR命輪<SummonPurple:「歪みし騎士の詩」>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップ・天井等の特殊ルール発動時を除き、すべての覚醒体または命輪は基礎確率が適用されます。詳細はルール説明をご確認ください。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲーム内で期間限定の遡行機能が開放され、覚醒体・命輪の育成または覚醒に投入したリソースを再配置する機会が提供されます。\n·この点をご理解・ご了承のうえ、リソースの投入を行ってください。\n\n"
  },
  Summon_138853_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:宿願の残響>】縛誓の諭において、SSRアイテムの基礎確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて覚醒体で、最大 30 回の覚醒で必ず天井によりSSR覚醒体またはSSR命輪を獲得できます。\n·覚醒でSSRを獲得した場合、33.33％の確率で今期UP対象のSSR覚醒体<SummonPurple:ポリュクス>およびSSR命輪<SummonPurple:「歪みし騎士の詩」>となります。\n·今回の覚醒で獲得したSSRが今期選定のSSR覚醒体または命輪でない場合、次回覚醒で獲得するSSRは必ず今期選定のSSR覚醒体または命輪となります。{s1}\n·現在、連続 {s2} 回今期選定外の覚醒体または命輪を獲得しています。{s3}\n·連続2回の覚醒で同じ今期UPアイテムを獲得した場合、次回覚醒で獲得するUPは必ずもう一方の今期UPアイテムとなります。\n·現在、連続 {s4} 回今期UP覚醒体を獲得しています。\n·現在、連続 {s5} 回今期UP命輪を獲得しています。\n\n<Title:【SRアイテム】>\n【<SummonPurple:宿願の残響>】イベント覚醒において、SRアイテムの基礎確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:【特別説明】>\n·覚醒でSSR命輪を獲得した際、副産物として根源沈殿を 50 個同時に獲得します。SR命輪を獲得した際は根源沈殿を 5 個、R命輪を獲得した際は根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一SSR命輪の 2〜16 回目の獲得時には、毎回自動的に重ね位レベルが上昇し「根源沈殿」×50を獲得します。17 回目以降の獲得時には「命途遡行の欠片」× 1、「根源沈殿」× 50、「薔薇金券」× 20000に変換されます。限定SSR命輪は「命途遡行の欠片」× 2、「根源沈殿」× 50、「薔薇金券」× 20000に変換されます。同一SSR覚醒体の 2〜16 回目の獲得時には、毎回対応する覚醒体の残片 1 個と根源沈殿 50 個に変換されます。17 回目以降の獲得時には、非限定SSR覚醒体は「魂魄遡行の欠片」× 1 と「根源沈殿」× 150に、限定SSR覚醒体は「魂魄遡行の欠片」× 2 と「根源沈殿」× 250に変換されます。ただし、任意選択方式（原質楽園、魂魄遡行のコア、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得した場合、または覚醒体の残片が溢れた場合は、根源沈殿への変換は行われません。\n·今回の覚醒は【縛誓の諭】に属し、いずれの【縛誓の諭】においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
