  Summon_138855_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:宿願の響き>】縛誓の諭において、SSRアイテムの基礎確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得するSSRアイテムはすべて覚醒体で、最大 30 回の覚醒で必ず天井によりSSR覚醒体またはSSR命輪を獲得できます。\n·覚醒でSSRを獲得した場合、33.33％の確率で今期UP対象のSSR覚醒体<SummonOrange:レク>とSSR命輪<SummonOrange:「幸運の時間」>になります。\n·今回の覚醒で獲得したSSRが今期選定のSSR覚醒体または命輪でない場合、次回覚醒で獲得するSSRは必ず今期選定のSSR覚醒体または命輪になります。{s1}\n·現在連続 {s2} 回、今期選定外の覚醒体または命輪を獲得しています。{s3}\n·連続2回の覚醒で同じ今期UPアイテムを獲得した場合、次回覚醒で獲得するUPは必ずもう一方の今期UPアイテムになります。\n·現在連続 {s4} 回、今期UP覚醒体を獲得しています。\n·現在連続 {s5} 回、今期UP命輪を獲得しています。\n\n<Title:【SRアイテム】>\n【<SummonOrange:宿願の響き>】イベント覚醒において、SRアイテムの基礎確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:【特別説明】>\n·覚醒でSSR命輪を獲得した場合、副産物として根源沈殿を 50 個同時に獲得します。SR命輪を獲得した場合、副産物として根源沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一SSR命輪を2〜16回目に獲得した場合、毎回自動的に重ね位レベルが上昇し「根源沈殿」×50を獲得します。17回目以降の獲得は「命途回溯の欠片」× 1、「根源沈殿」× 50、「薔薇金券」× 20000に変換されます。限定SSR命輪は「命途回溯の欠片」× 2、「根源沈殿」× 50、「薔薇金券」× 20000に変換されます。同一SSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の残片 1 個と根源沈殿 50 個に変換されます。17回目以降の獲得は、非限定SSR覚醒体は「魂魄回溯の欠片」× 1 と「根源沈殿」× 150に変換され、限定SSR覚醒体は「魂魄回溯の欠片」× 2 と「根源沈殿」× 250に変換されます。ただし、任意選択方式（原質楽園、魂魄回溯のコア、原型視界等を含む）およびランダム方式（原質捕獲·忘却篇等を含む）で覚醒体を獲得した場合、または覚醒体残片が溢れた場合は、根源沈殿への変換は行われません。\n·今回の覚醒は【縛誓の諭】に属し、いずれの【縛誓の諭】においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n\n"
  },
