  Summon_139916_LongDesc1 = {
    Text = "【<SummonPurple:誘心の医者>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UPキャラクター<SummonPurple:クレメンタイン>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:クレメンタイン>の覚醒取得確率がアップします。\n\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用します。具体的にはルール説明に従ってください。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再展開リソースの機会を提供するために期間限定の回溯機能を開始します。\n·この点を理解し受け入れた上で、リソース投入を行ってください。\n\n"
