  },
  Summon_139918_Desc = {
    Text = "<SummonOrange:5>回の召喚ごとにSR以上確定"
  },
  Summon_139918_LongDesc1 = {
    Text = "【<SummonOrange:冒涜楽章>】期間限定運命イベント覚醒が開催中。イベント期間中、秘密の守り人は期間限定イベントUP運命<SummonOrange:永遠のレクイエム>を覚醒できます。\n·イベント期間中、限定SSR運命<SummonOrange:永遠のレクイエム>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップ・天井などの特殊ルールを除き、すべての覚醒体または運命は基礎確率を使用します。詳細はルール説明をご確認ください。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・運命の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは期間限定の回溯機能を開放し、覚醒体・運命の育成または覚醒に対してリソースを再配置する機会を提供します。\n·この点をご理解・ご了承いただいた上で、リソースの投入を行ってください。\n\n"
  },
  Summon_139918_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:冒涜の賛歌>】限定命輪イベント覚醒中に、SSRアイテムの基本確率は3.03％、総合確率(保底を含む)は5.02％です。取得したSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底によりSSR命輪を入手できます。\n·覚醒でSSR命輪を取得した場合、50.00％の確率で今期UPのSSR命輪<SummonOrange:永遠のレクイエム>となります。\n·前回の覚醒で取得したSSR命輪が今期確率アップ命輪でない場合、次回の覚醒で取得するSSR命輪は必ず今期確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:冒涜の賛歌>】命輪イベント覚醒中に、SRアイテム覚醒の基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97％、SSRアイテムを取得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を取得した場合、同時に50個の根源の澱を副産物として得られます；SR命輪を取得した場合、同時に5個の根源の澱を副産物として得られます；R命輪を取得した場合、同時に1個の根源の澱を副産物として得られます。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回取得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の取得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯のコア等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において、保底覚醒回数は共に累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
