    Text = "SSR基本出現率：3.03%<color=#A3A6AB>（保証込み総合出現率：5.02%）</color>"
  },
  Summon_139920_ShortDesc = {
    Text = "出現する覚醒体は<SummonOrange:混沌>界域となる"
