  },
  Summon_140752_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonBlue:深海の道標>】期間限定命輪イベント覚醒において、SSRアイテムを取得する基礎確率は 3.03%、総合確率（天井含む）は 5.02% です。取得できるSSRアイテムはすべて命輪であり、最大 30 回の覚醒で必ず天井によりSSR命輪を取得できます。\n·覚醒によりSSR命輪を取得した際、50.00% の確率で今期UPのSSR命輪<SummonBlue:聖なる炎の導き>となります。\n·前回の覚醒で取得したSSR命輪が今期確率上昇命輪でなかった場合、次回覚醒で取得するSSR命輪は必ず今期確率上昇命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonBlue:深海の道標>】命輪イベント覚醒において、SRアイテム覚醒の基礎確率は 15.85%、総合確率（天井含む）は 25.00% です。この覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを取得でき、天井によりSRアイテムを取得する確率は 96.97%、SSRアイテムを取得する確率は 3.03% です。\n\n<Title:【特記事項】>\n·覚醒でSSR命輪を取得した際、副産物として同時に 50 個の根源の澱を取得します；SR命輪を取得した際、副産物として同時に 5 個の根源の澱を取得します；R命輪を取得した際、副産物として同時に 1 個の根源の澱を取得します。\n·いかなる方法（覚醒・ショップ交換・システム贈呈等を含むがこれに限らない）を問わず、同一SSR命輪を第 2〜16 回目に取得した場合、毎回自動的に強化レベルが上昇し「 根源の澱」×50 を取得します；第 17 回目以降に取得した場合、「廻命リセットの破片」× 1、「 根源の澱」× 50、「薔薇金券」× 20000 に変換され、限定SSR命輪は「廻命リセットの破片」× 2、「 根源の澱」× 50、「薔薇金券」× 20000 に変換されます。ただし、任意選択方式（輪転の書・廻命のコア等を含む）およびランダム方式（宿命が固定される·忘却篇等を含む）により命輪を取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属します。任意の【命輪イベント覚醒】において、天井カウントは共通で累計され、他の覚醒タイプの天井カウントとは独立して集計されます。"
  },
