  Summon_140754_LongDesc1 = {
    Text = "【<SummonOrange:霧境の来客>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUPキャラクター<SummonOrange:ムシェット>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:ムシェット>の覚醒取得確率が上昇します。\n·今回の期間限定イベント覚醒では、確率上昇・天井などの特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対して弱体化または強化のバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは期間限定リセット機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解・承諾した上で、リソースを投入するようにしてください。"
  },
  Summon_140754_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:雾境来客>】の期間限定キャラクターイベント覚醒において、SSRアイテムの基本確率は3.03%、総合確率(保底含む)は5.02%です。取得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を得ることができます。\n·覚醒でSSR覚醒体を取得した場合、33.33%の確率で今期UPのSSR覚醒体<SummonOrange:茉夏>となります。\n·連続して2回の覚醒で取得したSSR覚醒体が今期の確率アップキャラクターでない場合、次回の覚醒で得られるSSRキャラクターは必ず今期の確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回非今期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:雾境来客>】のキャラクターイベント覚醒において、SRアイテムの基本確率は15.85%、総合確率(保底含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを得ることができ、保底でSRアイテムを得る確率は96.97%、SSRアイテムを得る確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として得ます；R命輪を獲得した場合、同時に1個の根源の澱を副産物として得ます。\n·どのような方法(覚醒、ショップ交換、システムプレゼントなどを含む)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は「魂の回溯欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「魂の回溯欠片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、精神体カプセルなどを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において保底の覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。"
  },
