  },
  Summon_140756_Desc = {
    Text = "<SummonPurple:5>回の召喚ごとにSR以上確定"
  },
  Summon_140756_LongDesc1 = {
    Text = "【<SummonPurple:仮テキスト>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUP命輪<SummonPurple:ポリュクス>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonPurple:ポリュクス>の覚醒取得確率が上昇します。\n\n·今回の期間限定イベント覚醒では、確率上昇・天井などの特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対してナーフまたはバフのバランス調整が行われる場合があります。\n·ナーフが発生した場合、ゲームは期間限定回溯機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解・承諾した上で、リソースを投入するようにしてください。"
  },
  Summon_140756_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:仮テキスト>】限定命輪イベント覚醒において、SSRアイテムの基礎確率は 3.03%、総合確率（天井含む）は 5.02%です。取得できるSSRアイテムはすべて命輪であり、最大 30 回の覚醒で必ず天井によりSSR命輪を取得できます。\n·覚醒によりSSR命輪を取得した際、50.00%の確率で今期UPのSSR命輪<SummonPurple:ポリュクス>となります。\n·前回の覚醒で取得したSSR命輪が今期確率上昇命輪でなかった場合、次回覚醒で取得するSSR命輪は必ず今期確率上昇命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonPurple:仮テキスト>】命輪イベント覚醒において、SRアイテム覚醒の基礎確率は 15.85%、総合確率（天井含む）は 25.00%です。この覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを取得でき、天井によりSRアイテムを取得する確率は 96.97%、SSRアイテムを取得する確率は 3.03%です。\n\n<Title:【特記事項】>\n·覚醒でSSR命輪を取得した際、副産物として同時に 50 個の根源の澱を取得します；SR命輪を取得した際、副産物として同時に 5 個の根源の澱を取得します；R命輪を取得した際、副産物として同時に 1 個の根源の澱を取得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれらに限らない）を問わず、同一のSSR命輪を第 2〜16 回目に取得した際、毎回自動的に強化レベルが上昇し「 根源の澱」×50 を取得します；第 17 回目以降に取得した場合、「廻命リセットの破片」× 1、「 根源の澱」× 50、「薔薇金券」× 20000 に変換されます。限定SSR命輪は「廻命リセットの破片」× 2、「 根源の澱」× 50、「薔薇金券」× 20000 に変換されます。ただし、任意選択方式（輪転の書、廻命のコア等を含む）およびランダム方式（宿命が固定される·忘却篇等を含む）で命輪を取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属します。いずれの【命輪イベント覚醒】においても、天井の覚醒回数は共通で累計され、他の覚醒タイプの天井回数とは独立して計算されます。"
  },
