  Summon_14135_LongDesc1 = {
    Text = "【輪転の相】は常設の運命の札召喚で、守秘者は運命の札を獲得することができます。\n\n・【輪転の相】では「運命の札指定」を選択後、召喚を行います。\n「指定の運命の札」は召喚での獲得確率が大幅に増加します！\n\n・【輪転の相】では5回の召喚ごとに、1枚以上のSR以上の運命の札を獲得します。\n\n・【輪転の相】では特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は「召喚ルール」をご参照ください。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化されます場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_14135_LongDesc2 = {
    Text = "<Title:【SSR】>\n・【輪転の相】常設運命の札召喚において、SSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。\nSSRはすべて運命の札となり、最大30回の召喚で保証によりSSR運命の札を必ず獲得できます。\n・召喚でSSR運命の札を獲得した際、33.33%の確率で現在の指定運命の札となります。\n・獲得したSSR運命の札が2回連続で「指定の運命の札」でない場合、次の召喚で獲得するSSRは必ず「指定の運命の札」になります。\n・現在、{s1}回連続で「指定の運命の札」ではないものを獲得しています。\n・以下の忘却篇限定運命の札が「輪転の相」常設召喚に追加されました。「輪転の相」常設召喚においてSSR運命の札の総合出現率のうち0.5%を共同で分配します。これらの限定運命の札は指定選択できず、「輪転の書」からも獲得できません。\n ○ 運命の札「神王の頌歌」「痛みを越えて」「薔薇の名のもとに」「最も貴重な収蔵品」「隠秘の誕生」「女王の戒律」「神言石板」「畸体回噬」「慈悲の哺育」「虔誠なる偉力」「詩箋の句末」「幸運の時間」「永遠の安魂曲」「殷紅に沈む」「隠世の転輪」が「輪転の相」常設召喚に追加されました。\n\n<Title:【SR】>\n・【輪転の相】常設運命の札召喚において、SRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。この召喚のSRはすべて運命の札となります。\n・最大5回の召喚で保証によりSR以上を必ず獲得します。保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SSR運命の札を獲得すると、同時に50個の「根源の澱」を副産物として獲得します。SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR運命の札を獲得した場合、毎回自動的に重ね掛けレベルが上昇し、「根源の澱」×50を獲得します。17回目以降の獲得では、「命途回溯欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR運命の札は「命途回溯欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯のコアなど）およびランダム方式（宿命定格・忘却篇など）で運命の札を獲得した場合は、「根源の澱」には変換されません。\n・この召喚タイプは【常設運命の札召喚】に該当します。保証召喚回数は個別に累計され、他の召喚タイプのものとは、別個にカウントされます。\n"
  },
  Summon_14135_Name = {
    Text = "常設運命の札召喚"
  },
  Summon_14135_RateListTextR = {
    Text = "R基本出現率：81.12%<color=#A3A6AB>（保証込み総合出現率：69.98%）</color>"
