    Text = "【界域研究】は常設のキャラ召喚で、守秘者はいつでも指定界域を変更し、異なる界域の覚醒体を獲得することができます。現在【<SummonRed:血肉>】界域が指定されています。\n\n・【界域研究】では覚醒体を獲得した場合は必ず、指定の界域の覚醒体となります。\n\n・【界域研究】では特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は「召喚ルール」をご参照ください。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化されます場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_14142_LongDesc2 = {
    Text = "<Title:【SSR】>\n・【界域研究】常設キャラ召喚において、SSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。SSRはすべて覚醒体となり、最大30回の召喚で保証によりSSR覚醒体を必ず獲得できます。\n・以下の忘却篇限定覚醒体が「界域研究」常設召喚に追加されました。各界域の「界域研究」常設召喚においてSSR覚醒体の総合出現率のうち0.5%を共同で分配します。これらの限定覚醒体は引き続き「魔封瓶」からは獲得できません。\n ・<SummonOrange:「混沌」>界域：「リリー」「24」「レイク」「ハムリン」「ターヴィ」\n ・<SummonBlue:「深海」>界域：「トゥルー」「マーフィー」「ミリアム」\n ・<SummonRed:「血肉」>界域：「ソレイル」「サルヴァドル」「タイース」「血鎖·シロ」\n ・<SummonPurple:「超維」>界域：「ダフデル」「ワンダ」「オルラ」\n\n<Title:【SR】>\n・【界域研究】常設キャラ召喚において、SRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。この召喚のSRはすべて運命の札となります。\n・最大5回の召喚で保証によりSR以上を必ず獲得します。保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、毎回対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます。17回目以降の獲得では、非限定SSR覚醒体は「魂の回溯欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「魂の回溯欠片」×2と「根源の澱」×250に変換されます。ただし、任意選択方式（魔封瓶、魂の回溯のコア、原型視界など）およびランダム方式（根源の捕獲・忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は、「根源の澱」には変換されません。\n・この召喚は【常設キャラ召喚】に該当します。保証召喚回数は個別に累計され、他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n\n"
  },
