  Summon_141455_Desc = {
    Text = "<SummonBlue:5>回の召喚ごとにSR以上確定"
  },
  Summon_141455_LongDesc1 = {
    Text = "[<SummonBlue:暗海迷声>]期間限定命輪イベント覚醒が開催中です。イベント期間中、守秘者は期間限定イベントピックアップ命輪<SummonBlue:神王の頌歌>を覚醒で獲得できます。\n·イベント期間中、限定SSR命輪<SummonBlue:神王の頌歌>の覚醒獲得確率がアップします。\n·今回の期間限定イベント覚醒では、確率アップ・天井等の特殊ルール発動時を除き、すべての覚醒体または命輪は基礎確率が適用されます。詳細はルール説明をご確認ください。\n\n<Title:[バランス調整]>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、覚醒体・命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲーム内で期間限定の遡行機能が開放され、覚醒体・命輪の育成または覚醒に対してリソースを再配置する機会が提供されます。\n·この点をご理解・ご了承の上で、リソースの投入を行ってください。\n\n"
  },
  Summon_141455_LongDesc2 = {
    Text = "<Title:[SSRアイテム]>\n·[<SummonBlue:暗海の迷声>]期間限定命輪イベント覚醒において、SSRアイテムの基本確率は 3.03％、総合確率（天井含む）は 5.02％です。獲得できるSSRアイテムはすべて命輪で、最大 30 回の覚醒で天井によりSSR命輪を確定で獲得できます。\n·覚醒でSSR命輪を獲得した場合、50.00％の確率で今期PUのSSR命輪<SummonBlue:神王の頌歌>となります。\n·前回の覚醒で獲得したSSR命輪が今期確率UP命輪でなかった場合、次回覚醒で獲得するSSR命輪は必ず今期確率UP命輪となります。\n\n<Title:[SRアイテム]>\n·[<SummonBlue:暗海の迷声>]命輪イベント覚醒において、SRアイテムの基本確率は 15.85％、総合確率（天井含む）は 25.00％です。本覚醒のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で天井によりSR以上のアイテムを確定で獲得でき、天井でSRアイテムを獲得する確率は 96.97％、SSRアイテムを獲得する確率は 3.03％です。\n\n<Title:[特別説明]>\n·覚醒でSSR命輪を獲得した場合、副産物として根源の沈殿を 50 個同時に獲得します。SR命輪を獲得した場合、副産物として根源の沈殿を 5 個同時に獲得します。R命輪を獲得した場合、副産物として根源の沈殿を 1 個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第 2〜16 回獲得した場合、毎回自動的に重ねランクが上昇し、【根源の沈殿】×50を獲得します。第 17 回以降に獲得した場合、【運命遡行の欠片】× 1、【根源の沈殿】× 50、【薔薇金券】× 20000に変換されます。限定SSR命輪は【運命遡行の欠片】× 2、【根源の沈殿】× 50、【薔薇金券】× 20000に変換されます。ただし、任意選択方式（輪転の書、運命遡行のコア等を含む）およびランダム方式（宿命カット·忘却篇等を含む）で命輪を獲得した場合、根源の沈殿への変換は行われません。\n·今回の覚醒は[命輪イベント覚醒]に属し、いずれの[命輪イベント覚醒]においても天井覚醒回数は共通で累計され、他の覚醒タイプの天井覚醒回数とは独立して集計されます。\n"
  },
