  Summon_141455_Title = {
    Text = "暗い海のささやき"
  },
  Summon_141456_Desc = {
    Text = "<SummonPurple:5>回の覚醒ごとにSR以上確定"
  },
  Summon_141456_LongDesc1 = {
    Text = "【<SummonPurple:漆黒の羽>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定UPキャラクター<SummonPurple:カストル>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:カストル>の覚醒獲得確率がアップします。\n\n·今回の期間限定イベント覚醒では、確率アップや保底などの特殊ルールが発生しない限り、すべての覚醒体または命輪は基本確率を使用し、具体的にはルール説明に従います。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再配置リソースの機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこれを理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_141456_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:漆黒の羽>】限定キャラクターイベント覚醒中に、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した際、本期UPのSSR覚醒体<SummonPurple:カストル>である確率は33.33%です。\n·連続して2回の覚醒で獲得したSSR覚醒体が本期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず本期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回非本期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonPurple:漆黒の羽>】キャラクターイベント覚醒中に、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した際、同時に1個の根源の澱を副産物として獲得します。\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含む)でも第2〜16回に同じSSR覚醒体を獲得した場合、毎回対応する覚醒体の欠片1個と根源の澱50個に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は【灵魂回溯碎片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【灵魂回溯碎片】×2と【根源の澱】×250に変換されます。ただし、任意の選択方式(原質楽園、返魂のコア、原型視界などを含む)やランダムな方式(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】で保底覚醒回数が共同累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
