  Summon_14149_Title = {
    Text = "篠突く雨は紅く"
  },
  Summon_141834_Desc = {
    Text = "<SummonRed:5>回の覚醒ごとにSR以上確定"
  },
  Summon_141834_LongDesc1 = {
    Text = "【<SummonRed:甘い幻想>】時間制限付きキャラクターイベント覚醒が開始されました。イベント期間中、シークレットキーパーはここから時間制限付きイベントUPキャラクター<SummonRed:カラブ>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonRed:カラブ>の覚醒取得確率が上がります。\n·今回の時間制限付きイベント覚醒では、確率上昇・天井等の特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n·毎日おすすめ覚醒：今回の時間制限付きイベント覚醒では、シークレットキーパーは毎日60プラチナジェルの特別価格で1回覚醒でき、さらにシルバーコア60個が追加でプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対してナーフまたはバフのバランス調整を行う場合があります。\n·ナーフが発生した場合、ゲームは時間制限付き巻き戻し機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解・承諾した上で、リソースを投入するようにしてください。"
  },
  Summon_141834_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonRed:甘い幻想>】時間制限付きキャラクターイベント覚醒において、SSRアイテムを取得する基礎確率は 3.03%、総合確率（天井込み）は 5.02% です。取得できるSSRアイテムはすべて覚醒体であり、最大30回の覚醒で天井によってSSR覚醒体が必ず取得できます。\n·覚醒によってSSR覚醒体を取得した場合、33.33%の確率で今期UPのSSR覚醒体<SummonRed:カラブ>となります。\n·連続2回の覚醒で取得したSSR覚醒体が今期確率上昇キャラクターでない場合、次回覚醒で取得するSSRキャラクターは必ず今期確率上昇キャラクターとなります。{s1}\n·現在、今期UP以外のキャラクターを連続 {s2} 回取得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonRed:甘い幻想>】キャラクターイベント覚醒において、SRアイテムを取得する基礎確率は 15.85%、総合確率（天井込み）は 25.00% です。この覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で天井によってSR以上のアイテムが必ず取得でき、天井でSRアイテムを取得する確率は 96.97%、SSRアイテムを取得する確率は 3.03% です。\n\n<Title:【特別説明】>\n·覚醒でSR命輪を取得した場合、副産物として根源の澱5個を同時に取得します；R命輪を取得した場合、副産物として根源の澱1個を同時に取得します。\n·いかなる方法（覚醒・ショップ交換・システム贈呈等を含むがこれに限らない）によっても、同一のSSR覚醒体を第2〜16回目に取得した場合、その都度対応する覚醒体の欠片1個と根源の澱50個に変換されます；第17回目以降に取得した場合、非限定SSR覚醒体は「ソウルリセットの破片」× 1 と 「根源の澱」× 150 に変換され、限定SSR覚醒体は「ソウルリセットの破片」× 2 と「根源の澱」× 250 に変換されます。ただし、任意選択方式（魔封瓶・返魂のコア・精神体カプセル等を含む）およびランダム方式（セフィロトキャプチャ·忘却篇等を含む）によって覚醒体または溢出した覚醒体の欠片を取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【キャラクターイベント覚醒】に属します。いずれの【キャラクターイベント覚醒】においても、天井の覚醒回数は共通で累計され、他の覚醒タイプの天井回数とは独立して計算されます。"
  },
