  Summon_142860_Desc = {
    Text = "<SummonBlue:5>回の覚醒ごとにSR以上確定"
  },
  Summon_142860_LongDesc1 = {
    Text = "【<SummonBlue:崇尊誕生の儀式>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUPキャラクター<SummonBlue:偽誕・マーフィー>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonBlue:偽誕・マーフィー>の覚醒取得確率が上昇します。\n·今回の期間限定イベント覚醒では、確率上昇・天井などの特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対して弱体化または強化のバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは期間限定リセット機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解・承諾した上で、リソースを投入するようにしてください。"
  },
  Summon_142860_LongDesc2 = {
    Text = "<Title:【SSR】>\n【<SummonBlue:崇尊誕儀>】期間限定イベントキャラ召喚において、\nSSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。\nSSRはすべて覚醒体となり、最大30回の召喚で保証によりSSR覚醒体を必ず獲得できます。\n・召喚でSSR覚醒体を獲得した際、33.33%の確率で今回ピックアップのSSR覚醒体<SummonBlue:真貌・マーフィー>となります。\n・獲得したSSR覚醒体が2回連続で今回ピックアップのキャラでない場合、次の召喚で獲得するSSRは必ず今回ピックアップのキャラになります。{s1}\n・現在、{s2}回連続で、今回ピックアップのキャラではないものを獲得しています。{s3}\n\n<Title:【SR】>\n【<SummonBlue:崇尊誕儀>】キャラ召喚において、\nSRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。\nこの召喚のSRはすべて運命の札となります。\n・最大5回の召喚で保証によりSR以上を必ず獲得します。\n保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。\n・R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます。17回目以降は非限定SSR覚醒体は「魂溯の欠片」×1と「根源の澱」×150に変換されます。限定SSR覚醒体は「魂溯の欠片」×2と「根源の澱」×250に変換されます。\nただし、任意選択方式（魔封瓶、返魂のコア、精神体カプセルなど）およびランダム方式（根源の捕獲・忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は、「根源の澱」には変換されません。\n・この召喚タイプは【イベントキャラ召喚】に該当します。\nどの【イベントキャラ召喚】でも保証召喚回数は共通して累積されます。\n他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n\n"
  },
