  Summon_142865_LongDesc1 = {
    Text = "【<SummonOrange:死が約束通り>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUP命輪<SummonOrange:琥珀色の死>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:琥珀色の死>の覚醒取得確率が上昇します。\n\n·今回の期間限定イベント覚醒では、確率上昇・天井などの特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対してナーフまたはバフのバランス調整を行う場合があります。\n·ナーフが発生した場合、ゲームは期間限定リセット機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解・承諾した上で、リソースを投入するようにしてください。"
  },
  Summon_142865_LongDesc2 = {
    Text = "<Title:【SSR】>\n【<SummonOrange:死の約束>】期間限定イベント運命の札召喚において、SSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。SSRはすべて運命の札となり、最大30回の召喚で保証によりSSR運命の札を必ず獲得できます。\n・召喚でSSR運命の札を獲得した際、50.00%の確率で今回ピックアップのSSR運命の札<SummonOrange:琥珀色の死>となります。\n・前回獲得したSSR運命の札が今回ピックアップの運命の札でない場合、次の召喚で獲得するSSRは必ず今回ピックアップの運命の札になります。\n\n<Title:【SR】>\n【<SummonOrange:死の約束>】運命の札召喚において、SRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。この召喚のSRはすべて運命の札となります。\n・最大5回の召喚で保証によりSR以上を必ず獲得します。保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SSR運命の札を獲得すると、同時に50個の「根源の澱」を副産物として獲得します。SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いかなる方法（召喚、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一SSR運命の札を2〜16回目に獲得した場合、毎回自動的に重ねランクが上昇し「根源の澱」×50を獲得します。17回目以降の獲得は「運命遡行の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR運命の札は「運命遡行の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、運命遡行のコア等を含む）およびランダム方式（宿命カット·忘却篇等を含む）で運命の札を獲得した場合、根源の澱への変換は行われません。\n・この召喚タイプは【イベント運命の札召喚】に該当します。どの【イベント運命の札召喚】でも保証召喚回数は共通して累積されます。他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n"
  },
