    Text = "粉砂糖の囁き"
  },
  Summon_149326_Desc = {
    Text = "<SummonOrange:30>回ごとの覚醒で必ず上記の対象が排出されます！"
  },
  Summon_149326_LongDesc1 = {
    Text = "【<SummonOrange:胸に星を求めて>】百相自選覚醒時間制限付き覚醒が開始されました。イベント期間中、シークレットキーパーはここから<SummonOrange:自由に選択した>指定数の覚醒体を選定でき、選ばれた覚醒体およびその推薦命輪が今回の覚醒イベントのSSRリストとなります。\n\n·イベント期間中、覚醒で獲得するSSRは必ず選定した覚醒体または命輪となります。\n·今回の百相自選覚醒時間制限付き覚醒では、確率アップ・天井などの特殊ルールを除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n·毎日おすすめ覚醒：今回の時間制限付きイベント覚醒では、シークレットキーパーは毎日60プラチナジェルの割引価格で1回覚醒でき、さらに60シルバーコアが追加でプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対してナーフまたはバフのバランス調整を行う場合があります。\n·ナーフが発生した際、ゲームは時間制限付きの巻き戻し機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置できる機会を提供します。\n·この点を十分に理解・承諾した上で、リソースを投入してください。\n\n"
  },
  Summon_149326_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n·【<SummonOrange:胸に星を求めて>】百相自選覚醒時間制限付き覚醒では、SSRアイテムを獲得する基礎確率は 3.03%、総合確率（天井含む）は 5.02% です。30 回覚醒ごとに必ず天井により選定したSSR覚醒体またはSSR命輪を獲得できます。\n·覚醒でSSRを獲得した際、33.33% の確率で今期選定のSSR<SummonOrange:覚醒体>となります。\n·連続 2 回の覚醒で獲得したSSRが命輪だった場合、次回覚醒で獲得するSSRは必ず覚醒体となります。\n·連続 2 回の覚醒で獲得したSSRが覚醒体だった場合、次回覚醒で獲得するSSRは必ず命輪となります。\n·現在、連続 {s1} 回SSR覚醒体を獲得しています。\n·現在、連続 {s2} 回SSR命輪を獲得しています。\n\n<Title:【SRアイテム】>\n·【<SummonOrange:胸に星を求めて>】イベント覚醒では、SRアイテムを獲得する基礎確率は 15.85%、総合確率（天井含む）は 25.00% です。この覚醒内のSRアイテムはすべて命輪です。\n·最大 5 回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は 96.97%、SSRアイテムを獲得する確率は 3.03% です。\n\n<Title:【特記事項】>\n·覚醒でSSR命輪を獲得した際、副産物として根源の澱 50 個を同時に獲得します；覚醒でSR命輪を獲得した際、副産物として根源の澱 5 個を同時に獲得します；R命輪を獲得した際、副産物として根源の澱 1 個を同時に獲得します。\n·いかなる方法（覚醒・ショップ交換・システム配布等を含むがこれに限らない）を問わず、同一SSR命輪を第 2〜16 回目に獲得した際は、毎回自動的に重複位置レベルが上昇し「 根源の澱」×50 を獲得します；第 17 回目以降に獲得した場合、限定SSR命輪は「廻命リセットの破片」× 2・「 根源の澱」× 50・「薔薇金券」× 20000 に変換されます。同一SSR覚醒体を第 2〜16 回目に獲得した際は、毎回対応する覚醒体の欠片 1 個と根源の澱 50 個に変換されます；第 17 回目以降に獲得した場合、限定SSR覚醒体は「ソウルリセットの破片」× 2 と「根源の澱」× 250 に変換されます。ただし、任意選択方式（魔封瓶・返魂のコア・精神体カプセル等を含む）およびランダム方式（セフィロトキャプチャ·忘却篇等を含む）で覚醒体を獲得した場合や覚醒体の欠片が溢れた場合は、根源の澱への変換は行われません。\n·今回の覚醒は【百相自選覚醒】に属します。いずれかの【百相自選覚醒】において、天井カウントは共通で累計され、他の覚醒タイプの天井カウントとは独立して集計されます。\n\n"
  },
