  Summon_55881_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:エピファニの海>】の期間限定命輪イベント覚醒において、SSRアイテムの基本確率は3.03％、総合確率(保底含む)は5.02％です。取得したSSRアイテムはすべて命輪であり、最大30回の覚醒で必ず保底でSSR命輪を取得できます。\n·覚醒によってSSR命輪を取得した場合、50.00％の確率で今回のUP SSR命輪<SummonOrange:至高の収蔵品>となります。\n·前回の覚醒で取得したSSR命輪が今回の確率アップ命輪でない場合、次回の覚醒で取得するSSR命輪は必ず今回の確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:エピファニの海>】の命輪イベント覚醒において、SRアイテムの覚醒基本確率は15.85％、総合確率(保底含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底でSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97％、SSRアイテムを取得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を取得した場合、同時に50個の根源の澱が副産物として得られます；SR命輪を取得した場合、同時に5個の根源の澱が副産物として得られます；R命輪を取得した場合、同時に1個の根源の澱が副産物として得られます。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回取得した場合、毎回自動的に叠位レベルが上昇し「根源の澱」×50を取得します；第17回以降の取得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において、保底覚醒回数は共同で累計され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
