  Summon_55890_LongDesc1 = {
    Text = "【<SummonPurple:ソウルディスパッチ>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定のUPキャラクター<SummonPurple:ダフォダイル>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:ダフォダイル>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonPurple:ダフォダイル>は、初回UP後3〜9ヶ月の期間限定キャラクターイベント覚醒に引き続き登場し、約1年後に【界域研習】常駐キャラクター覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールが発生しない限り、すべての覚醒体や命輪は基本確率が適用され、具体的なルール説明に従います。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドで1回の覚醒をお得に行うことができ、さらに60シルバーコアをプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームのプレイスタイルに特有の理由から、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した際、ゲームは覚醒体や命輪の育成または覚醒のためにリソースを再配置する機会を提供するために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_55890_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:ソウルディスパッチ>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体であり、最大30回の覚醒で必ず保底によってSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、本期UPのSSR覚醒体<SummonPurple:ダフォダイル>である確率は33.33%です。\n·連続して2回の覚醒で獲得したSSR覚醒体が本期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず本期確率アップキャラクターになります。{s1}\n·現在、連続{s2}回非本期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonPurple:ソウルディスパッチ>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によってSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱が副産物として得られます。R命輪を獲得した場合、同時に1個の根源の澱が副産物として得られます。\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含む)であっても、第2〜16回に同じSSR覚醒体を獲得した場合、各回は対応する覚醒体の欠片1個と根源の澱50個に変換されます。第17回以降に獲得した場合、非限定SSR覚醒体は【ソウルトレース欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【ソウルトレース欠片】×2と【根源の澱】×250に変換されます。ただし、選択方式(原質楽園、返魂のコア、原型視界などを含む)やランダム方式(原質捕獲·忘却篇などを含む)で覚醒体や溢れた覚醒体の欠片を獲得した場合は、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数が共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
