  },
  Summon_66910_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:赤い雨が降り注ぐ>】の期間限定命輪イベント覚醒中、SSRアイテムを取得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。取得したSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底でSSR命輪を得ることができます。\n·覚醒でSSR命輪を取得した際、本期UPのSSR命輪<SummonOrange:深紅に沈む>である確率は50.00%です。\n·前回の覚醒で取得したSSR命輪が本期確率アップ命輪でない場合、次回の覚醒で取得するSSR命輪は必ず本期確率アップ命輪になります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:赤い雨が降り注ぐ>】の命輪イベント覚醒中、SRアイテムの覚醒基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底でSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97%、SSRアイテムを取得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を取得する際、同時に50個の根源の澱を副産物として取得します；SR命輪を取得する際、同時に5個の根源の澱を副産物として取得します；R命輪を取得する際、同時に1個の根源の澱を副産物として取得します。\n·いずれの方法（覚醒、商店交換、システム贈与などを含むがこれに限らない）でも、2〜16回目に同じSSR命輪を取得した場合、毎回自動的に叠位レベルが上昇し「根源の澱」×50を取得します；17回目以降の取得では、「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯のコアなど）およびランダム方式（宿命定格·忘却篇など）で命輪を取得した場合は、根源の澱には変換されません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
  Summon_66910_Name = {
    Text = "命輪イベント覚醒"
  },
  Summon_66910_ProbabilityUpDesc = {
    Text = "<SummonOrange:「殷紅に沈む」>取得確率がアップ！"
  },
  Summon_66910_RateListTextR = {
    Text = "R基本出現率：81.12%<color=#A3A6AB>（保証込み総合出現率：69.98%）</color>"
  },
  Summon_66910_RateListTextSR = {
    Text = "SR基本出現率：15.85％<color=#A3A6AB>（保証込み総合出現率：25.00％）</color>"
  },
  Summon_66910_RateListTextSSR = {
    Text = "SSR基本出現率：3.03%<color=#A3A6AB>（保証込み総合出現率：5.02%）</color>"
  },
  Summon_66910_Title = {
    Text = "赤い雨が降り注ぐ"
  },
  Summon_66911_Desc = {
    Text = "毎回<SummonOrange:5>回の覚醒で必ずSR級以上の命輪が出現する"
  },
  Summon_66911_LongDesc1 = {
    Text = "【<SummonOrange:存続の理>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定イベントUP命輪<SummonOrange:慈悲深き哺育>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:慈悲深き哺育>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR命輪<SummonOrange:慈悲深き哺育>は、初回UP後3～9ヶ月の期間限定命輪イベント覚醒に引き続き登場し、約1年後に【輪転の相】常駐命輪覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールを除いて、すべての覚醒体または命輪は基本確率で使用されます。具体的にはルール説明に従います。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドで1回の覚醒をお得に行え、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【バランス調整】>\n·ゲームのプレイスタイルに特有のため、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは限時回溯機能を開放し、覚醒体や命輪の育成や覚醒にリソースを再配置する機会を提供します。\n·必ずこれを承知の上で、リソース投入を行ってください。\n\n"
  },
  Summon_66911_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:存続の理>】の期間限定命輪イベント覚醒中、SSRアイテムを得る基本確率は3.03％、総合確率(保底を含む)は5.02％です。得られるSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底によりSSR命輪を取得できます。\n·覚醒でSSR命輪を取得した場合、本期UPのSSR命輪<SummonOrange:慈悲深き哺育>である確率は50.00％です。\n·前回覚醒で得たSSR命輪が本期確率アップ命輪でない場合、次回覚醒で得られるSSR命輪は必ず本期確率アップ命輪になります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:存続の理>】の命輪イベント覚醒中、SRアイテムの覚醒基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを得られ、保底でSRアイテムを得る確率は96.97％、SSRアイテムを得る確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を得た際、同時に50個の根源の澱が副産物として得られます；SR命輪を得た際は、同時に5個の根源の澱が副産物として得られます；R命輪を得た際は、同時に1個の根源の澱が副産物として得られます。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の獲得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱は変換されません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
