  },
  Summon_66915_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:冒涜の賛歌>】限定命輪イベント覚醒中にSSRアイテムを獲得する基本確率は3.03％、総合確率(保底を含む)は5.02％です。獲得したSSRアイテムは全て命輪で、最大30回の覚醒で必ず保底によりSSR命輪を獲得できます。\n·覚醒でSSR命輪を獲得した際、本期UPのSSR命輪<SummonOrange:永遠のレクイエム>である確率は50.00％です。\n·前回の覚醒で獲得したSSR命輪が本期確率アップ命輪でない場合、次回の覚醒で獲得するSSR命輪は必ず本期確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:冒涜の賛歌>】命輪イベント覚醒中にSRアイテムの覚醒基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムは全て命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別説明】>\n·覚醒でSSR命輪を獲得した際、同時に50個の根源の澱を副産物として獲得します；SR命輪を獲得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した際、同時に1個の根源の澱を副産物として獲得します。\n·いずれの方法（覚醒、商店交換、システム贈与などを含むがこれに限らない）でも、2〜16回目に同じSSR命輪を獲得した場合、毎回自動的に叠位レベルが上昇し「根源の澱」×50を獲得します；17回目以降の獲得では、「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯のコアなど）およびランダム方式（宿命定格·忘却篇など）で命輪を獲得した場合は、根源の澱には変換されません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において保底覚醒回数は共通に累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
