  Summon_66919_LongDesc1 = {
    Text = "【<SummonRed:復讐の獣>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUPキャラクター<SummonRed:ブラッドチェーン・ヘロット>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonRed:ブラッドチェーン・ヘロット>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonRed:ブラッドチェーン・ヘロット>は初回UP後3〜9ヶ月の期間限定キャラクターイベント覚醒に引き続き登場し、約1年後に【界域研習】常駐キャラクター覚醒に入ります。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールを除き、すべての覚醒体または命輪は基本確率を使用します。詳細はルール説明に従ってください。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドの割引で1回覚醒でき、さらに60シルバーコアが贈呈されます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を保つために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再リソース配置の機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_66919_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonRed:復讐の獣>】の期間限定キャラクターイベント覚醒中、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した際、本期UPのSSR覚醒体<SummonRed:血鎖・ヘロット>である確率は33.33%です。\n·連続して2回の覚醒で獲得したSSR覚醒体が本期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず本期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回本期UPキャラクター以外を獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonRed:復讐の獣>】のキャラクターイベント覚醒中、SRアイテムを獲得する基本確率は15.85%、総合確率(保底含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した際は、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含む)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は【魂溯の欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【魂溯の欠片】×2と【根源の澱】×250に変換されます。ただし、選択方式(原質楽園、魂溯のコア、原型視界などを含む)やランダム方式(原質捕獲・忘却篇など)で獲得した覚醒体または溢れた覚醒体の欠片については、根源の澱に変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共に累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
