  Summon_66924_Title = {
    Text = "紙が灰になる"
  },
  Summon_66925_Desc = {
    Text = "<SummonOrange:5>回の覚醒ごとにSR以上確定"
  },
  Summon_66925_LongDesc1 = {
    Text = "【<SummonOrange:運命のプレイヤー>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定UPキャラクター<SummonOrange:ライカー>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:ライカー>の覚醒取得確率がアップします。\n·イベント終了後、限定SSR覚醒体<SummonOrange:ライカー>は初回UP後3〜9ヶ月の期間限定キャラクターイベント覚醒に引き続き登場し、約1年後に【界域研習】常駐キャラクター覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的なルールは説明に従います。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドの割引価格で1回覚醒でき、さらに60シルバーコアをプレゼントします。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再配置リソースの機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し受け入れた上で、リソースの投入を行ってください。\n\n"
  },
  Summon_66925_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:運命のプレイヤー>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底含む)は5.02%です。獲得したSSRアイテムは全て覚醒体であり、最大30回の覚醒で必ず保底によりSSR覚醒体を取得できます。\n·覚醒でSSR覚醒体を獲得した場合、本期UPのSSR覚醒体<SummonOrange:ライカー>である確率は33.33%です。\n·連続して2回の覚醒で獲得したSSR覚醒体が本期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず本期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回非本期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:運命のプレイヤー>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保底含む)は25.00%です。本覚醒内のSRアイテムは全て命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含む)であっても、第2〜16回に同じSSR覚醒体を獲得した際、それぞれ1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は【魂の回溯欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【魂の回溯欠片】×2と【根源の澱】×250に変換されます。ただし、任選方式(原質楽園、魂の回溯のコア、原型視界などを含む)やランダム方式(原質捕獲·忘却篇など)で覚醒体や溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
