  },
  Summon_66926_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n「<SummonOrange:万律奏鳴>」限定キャラクターイベント覚醒中、SSRアイテムの基本確率は3.03％、総合確率(保底を含む)は5.02％です。取得したSSRアイテムはすべて覚醒体であり、最大30回の覚醒で必ず保底によりSSR覚醒体を取得できます。\n·覚醒でSSR覚醒体を取得した際、33.33％の確率で今期UPのSSR覚醒体<SummonOrange:ハムリン>になります。\n·連続して2回の覚醒で取得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で取得するSSRキャラクターは必ず今期確率アップキャラクターになります。{s1}\n·現在、連続{s2}回非今期UPキャラクターを取得しています。{s3}\n\n<Title:【SRアイテム】>\n「<SummonOrange:万律奏鳴>」キャラクターイベント覚醒中、SRアイテムの基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97％、SSRアイテムを取得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を取得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を取得した際は、同時に1個の根源の澱を副産物として獲得します。\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含む)であっても、第2〜16回に同じSSR覚醒体を取得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に取得した場合、非限定SSR覚醒体は「魂溯の欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「魂溯の欠片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、魂溯のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体や余剰覚醒体の欠片を取得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
