    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:汚れの付かない花>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体であり、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、本期UPのSSR覚醒体<SummonOrange:リリー>である確率は33.33%です。\n·連続して2回覚醒で獲得したSSR覚醒体が本期確率アップキャラクターでない場合、次回覚醒で獲得するSSRキャラクターは必ず本期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回本期UPキャラクターでないものを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:汚れの付かない花>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保底含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含む)で第2〜16回目に同じSSR覚醒体を獲得した場合、各回ごとに1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回目以降に獲得した場合、非限定SSR覚醒体は【灵魂回溯碎片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【灵魂回溯碎片】×2と【根源の澱】×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、いかなる【キャラクターイベント覚醒】においても保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
