  Summon_66933_LongDesc1 = {
    Text = "【<SummonOrange:勝利の夜>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定のUP命輪<SummonOrange:幸運の時>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:幸運の時>の覚醒取得確率がアップします。\n·イベント終了後、限定SSR命輪<SummonOrange:幸運の時>は初回UP後3〜9ヶ月の期間限定命輪イベント覚醒に引き続き登場し、約1年後には【輪転の相】常駐命輪覚醒に入ります。\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に準じます。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドでお得に1回覚醒でき、さらに60シルバーコアがプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を削弱または強化するバランス調整を行う場合があります。\n·削弱が発生した場合、ゲームは期間限定の回溯機能を開放し、覚醒体や命輪の育成または覚醒にリソースを再配置する機会を提供します。\n·このことを理解し、受け入れた上でリソースを投入してください。\n\n"
  },
