  Summon_66943_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonRed:神の意志を代行する>】限定キャラクターイベント覚醒中に、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した際、本期UPのSSR覚醒体<SummonRed:サルバドル>である確率は33.33%です。\n·連続して2回覚醒で獲得したSSR覚醒体が本期の確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず本期の確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回非本期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonRed:神の意志を代行する>】キャラクターイベント覚醒中に、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した際、同時に1個の根源の澱を副産物として獲得します。\n·どのような方法(覚醒、ショップ交換、システムプレゼントなどを含む)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降の獲得では、非限定SSR覚醒体は【魂の回溯欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【魂の回溯欠片】×2と【根源の澱】×250に変換されます。ただし、任意の方法(原質楽園、魂の回溯のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体や溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】で保底覚醒回数が共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
