  Summon_66945_Title = {
    Text = "深く囚われた願い"
  },
  Summon_66946_Desc = {
    Text = "<SummonOrange:5>回の覚醒ごとにSR以上確定"
  },
  Summon_66946_LongDesc1 = {
    Text = "【<SummonOrange:亦如本我>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UPキャラクター<SummonOrange:「24」>を呼び出すことができます。\n·イベント期間中、限定SSR覚醒体<SummonOrange:「24」>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonOrange:「24」>は、初回UP後3〜9ヶ月の期間限定キャラクターイベント覚醒に引き続き登場し、約1年後に【界域研習】常駐キャラクター覚醒に入ります。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールが発生しない限り、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に従います。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドで1回の割引覚醒が可能で、さらに60シルバーコアが贈呈されます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再配置リソースの機会を提供するために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上でリソースの投入を行ってください。\n\n"
  },
  Summon_66946_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:亦如本我>】の期間限定キャラクターイベント覚醒において、SSRアイテムの基本確率は3.03%、総合確率(保底を含む)は5.02%です。取得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を取得できます。\n·覚醒でSSR覚醒体を取得した際、33.33%の確率で今期UPのSSR覚醒体<SummonOrange:「24」>となります。\n·連続して2回の覚醒で取得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で得られるSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回、今期UPキャラクターでないものを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:亦如本我>】キャラクターイベント覚醒において、SRアイテムの基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97%、SSRアイテムを取得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を取得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を取得した際は、同時に1個の根源の澱を副産物として獲得します。\n·どのような方法(覚醒、ショップ交換、システムプレゼントなどを含む)であっても、第2〜16回に同じSSR覚醒体を取得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降の取得では、非限定SSR覚醒体は【魂の回溯欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【魂の回溯欠片】×2と【根源の澱】×250に変換されます。ただし、任意の方法(原質楽園、魂の回溯のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体や溢れた覚醒体の欠片を取得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
