  Summon_66958_LongDesc1 = {
    Text = "【<SummonOrange:エーテリアル・グローリー>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者は期間限定イベントUP命輪<SummonOrange:隠匿された誕生>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:隠匿された誕生>の覚醒獲得確率がアップします。\n·イベント終了後、限定SSR命輪<SummonOrange:隠匿された誕生>は初回UP後3〜9ヶ月の期間限定命輪イベント覚醒に出現し、約1年後に【輪転の相】常駐命輪覚醒に入ります。\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールを除き、すべての覚醒体または命輪は基本確率を使用し、具体的なルールは説明に従います。\n·毎日推奨覚醒：今回の期間限定イベント覚醒で、守秘者は毎日60ソースリキッドでお得に1回覚醒でき、さらに60シルバーコアがプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは期間限定の回溯機能を開放し、覚醒体や命輪の育成や覚醒にリソースを再配置する機会を提供します。\n·必ずこの点を理解し受け入れた上で、リソースを投入してください。\n\n"
  },
  Summon_66958_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:エーテリアル・グローリー>】の期間限定命輪イベント覚醒中、SSRアイテムを獲得する基本確率は3.03％、総合確率(保底を含む)は5.02％です。獲得したSSRアイテムは全て命輪で、最大30回の覚醒で必ず保底でSSR命輪を獲得できます。\n·覚醒でSSR命輪を獲得した際、50.00％の確率で今期UPのSSR命輪<SummonOrange:隠匿された誕生>となります。\n·前回の覚醒で獲得したSSR命輪が今期確率アップ命輪でない場合、次回の覚醒で獲得するSSR命輪は必ず今期確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:エーテリアル・グローリー>】の命輪イベント覚醒中、SRアイテムの覚醒基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムは全て命輪です。\n·最大5回の覚醒で必ず保底でSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を獲得した際、同時に50個の根源の澱を副産物として獲得します；SR命輪を獲得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した際、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を2〜16回目に獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；17回目以降に獲得した場合、「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】で保底覚醒回数が共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
