  Summon_66961_LongDesc1 = {
    Text = "【<SummonOrange:暗海からの呼び声>】期間限定イベント運命の札召喚が開始しました。\n期間中、守秘者は期間限定の運命の札<SummonOrange:神王の讃歌>を召喚で獲得できます。\n\n・期間中、限定SSR運命の札<SummonOrange:神王の讃歌>の召喚での出現率が増加します。\n\n・期間終了後も、限定SSR運命の札<SummonOrange:神王の讃歌>は最初の登場後、3～9か月の間の期間限定の運命の札召喚に引き続き登場し、約1年後に【輪転の書】常設運命の札召喚に追加されます。\n\n・今回の期間限定の運命の札召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は「召喚ルール」をご参照ください。\n\n・毎日のおすすめ召喚：今回の期間限定の運命の札召喚では、守秘者は毎日60プラチナジェルで1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_66961_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n·【<SummonOrange:暗い海のささやき>】限定命輪イベント覚醒中に、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底によりSSR命輪を獲得できます。\n·覚醒でSSR命輪を獲得した場合、本期UPのSSR命輪<SummonOrange:神王の讃歌>である確率は50.00%です。\n·前回の覚醒で獲得したSSR命輪が本期確率アップの命輪でない場合、次回の覚醒で獲得するSSR命輪は必ず本期確率アップの命輪となります。\n\n<Title:【SRアイテム】>\n·【<SummonOrange:暗い海のささやき>】命輪イベント覚醒中に、SRアイテムの覚醒の基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別説明】>\n·覚醒でSSR命輪を獲得した場合、同時に50個の根源の澱が副産物として獲得されます；SR命輪を獲得した場合、同時に5個の根源の澱が副産物として獲得されます；R命輪を獲得した場合、同時に1個の根源の澱が副産物として獲得されます。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回獲得した場合、毎回自動的に叠位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の獲得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】で保底覚醒回数が共同累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
