  },
  Summon_71229_Desc = {
    Text = "毎 <SummonRed:5> 回の覚醒で必ずSR級以上の対象が出現します"
  },
  Summon_71229_LongDesc1 = {
    Text = "【<SummonRed:神の意志を代行する>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UPキャラクター<SummonRed:サルバドール>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonRed:サルバドール>の覚醒獲得確率がアップします。\n·イベント終了後、限定SSR覚醒体<SummonRed:サルバドール>は初回UP後3〜9ヶ月の期間限定キャラクターイベント覚醒に登場し、約1年後に【界域研習】常駐キャラクター覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に従います。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドで1回の覚醒ができ、さらに60シルバーコアがプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再配置資源の機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上で資源を投入してください。\n\n"
  },
  Summon_71229_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonRed:神の意志を代行する>】期間限定キャラクターイベント覚醒中、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底でSSR覚醒体を取得できます。\n·覚醒でSSR覚醒体を獲得した際、33.33%の確率で今回のUP SSR覚醒体<SummonRed:サルバドル>となります。\n·連続して2回覚醒で獲得したSSR覚醒体が今回の確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今回の確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回非今回UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonRed:神の意志を代行する>】キャラクターイベント覚醒中、SRアイテムを獲得する基本確率は15.85%、総合確率(保底含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底でSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した際、同時に5つの根源の澱を副産物として獲得します。R命輪を獲得した際には、同時に1つの根源の澱を副産物として獲得します。\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含む)で第2〜16回目に同じSSR覚醒体を獲得した場合、毎回1つの対応する覚醒体の欠片と50個の根源の澱に変換されます。17回目以降に獲得した場合、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、精神体カプセルなどを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体や溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】で保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
  Summon_71229_Name = {
    Text = "キャラクターイベント覚醒"
  },
  Summon_71229_ProbabilityUpDesc = {
    Text = "<SummonRed:「サルバドール」>の取得確率がアップ！"
  },
  Summon_71229_RateListTextR = {
    Text = "R基本出現率：81.12%<color=#A3A6AB>（保証込み総合出現率：69.98%）</color>"
  },
  Summon_71229_RateListTextSR = {
    Text = "SR基本出現率：15.85％<color=#A3A6AB>（保証込み総合出現率：25.00％）</color>"
  },
  Summon_71229_RateListTextSSR = {
    Text = "SSR基本出現率：3.03%<color=#A3A6AB>（保証込み総合出現率：5.02%）</color>"
  },
  Summon_71229_ShortDesc = {
    Text = "獲得した覚醒体は必ず<SummonRed:血肉>境界である"
  },
  Summon_71229_Title = {
    Text = "神の意志を代行する"
  },
  Summon_74367_Desc = {
    Text = "<SummonBlue:5>回の召喚ごとにSR以上確定"
  },
  Summon_74367_LongDesc1 = {
    Text = "【<SummonBlue:天火領航>】期間限定イベントキャラ召喚が開始しました。\n期間中、守秘者は期間限定キャラ<SummonBlue:コーパサント>を召喚で獲得できます。\n·期間中、限定SSR覚醒体<SummonBlue:コーパサント>の召喚での出現率が増加します。\n·今回の期間限定キャラ召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は【召喚ルール】をご参照ください。\n·毎日のおすすめ召喚：今回の期間限定キャラ召喚では、守秘者は毎日60プラチナジェルで1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【注意】>\n·ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n·効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n·以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_74367_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonBlue:天火の先導>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した際、本期UPのSSR覚醒体<SummonBlue:コーパサント>である確率は33.33%です。\n·連続して2回覚醒で獲得したSSR覚醒体が本期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず本期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回本期UPキャラクターでないキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonBlue:天火の先導>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムが獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した際は、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含む)で第2〜16回目に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回目以降に獲得した場合、非限定SSR覚醒体は【灵魂回溯碎片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【灵魂回溯碎片】×2と【根源の澱】×250に変換されます。しかし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲・忘却篇など)で覚醒体や溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
