  Summon_77953_Desc = {
    Text = "<SummonPurple:5>回の召喚ごとにSR以上確定"
  },
  Summon_77953_LongDesc1 = {
    Text = "【<SummonPurple:一時的なテキスト>】時間制限付きキャラクターイベント覚醒が開始されました。イベント期間中、シークレットキーパーはここから時間制限付きイベントUPキャラクター<SummonPurple:暮星·ティンクト>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:暮星·ティンクト>の覚醒取得確率が上がります。\n·今回の時間制限付きイベント覚醒では、確率上昇・天井等の特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n·毎日おすすめ覚醒：今回の時間制限付きイベント覚醒では、シークレットキーパーは毎日60プラチナジェルの特別価格で1回覚醒でき、さらにシルバーコア60個が追加でプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対してナーフまたはバフのバランス調整を行う場合があります。\n·ナーフが発生した場合、ゲームは時間制限付き巻き戻し機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解・承諾した上で、リソースを投入するようにしてください。"
  },
  Summon_77953_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:臨時テキスト>】限定キャラクターイベント覚醒において、SSRアイテムの基礎確率は3.03%、総合確率（天井含む）は5.02%です。獲得したSSRアイテムはすべて覚醒体であり、最大30回の覚醒で必ず天井によりSSR覚醒体を獲得できます。\n·覚醒によりSSR覚醒体を獲得した際、33.33%の確率で今期UPのSSR覚醒体<SummonPurple:暮星・ティンクト>となります。\n·連続2回の覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでなかった場合、次回覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回、今期UPキャラクター以外を獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonPurple:臨時テキスト>】キャラクターイベント覚醒において、SRアイテムの基礎確率は15.85%、総合確率（天井含む）は25.00%です。この覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別説明】>\n·覚醒でSR命輪を獲得した際、副産物として根源の澱を5個同時に獲得します；R命輪を獲得した際、副産物として根源の澱を1個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれらに限らない）を問わず、同一のSSR覚醒体を2〜16回目に獲得した場合、毎回対応する覚醒体の欠片×1と根源の澱×50に変換されます；17回目以降に獲得した場合、非限定SSR覚醒体は「ソウルリセットの破片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「ソウルリセットの破片」×2と「根源の澱」×250に変換されます。ただし、任意選択方式（魔封瓶、返魂のコア、精神体カプセル等を含む）およびランダム方式（セフィロトキャプチャ·忘却篇等を含む）により覚醒体または覚醒体の欠片の溢れ分を獲得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【キャラクターイベント覚醒】に属します。任意の【キャラクターイベント覚醒】において、天井の覚醒回数は共通で累計され、他の覚醒タイプの天井回数とは独立して計算されます。"
  },
  Summon_77953_Name = {
    Text = "イベントキャラ召喚"
