  Summon_77953_ShortDesc = {
    Text = "出現する覚醒体は<SummonPurple:超次元>界域となる"
  },
  Summon_77953_Title = {
    Text = "仮テキスト"
  },
  Summon_77955_Desc = {
    Text = "<SummonBlue:5>回の召喚ごとにSR以上確定"
  },
  Summon_77955_LongDesc1 = {
    Text = "【<SummonBlue:仮テキスト>】期間限定イベントキャラ召喚が開始しました。期間中、守秘者は期間限定キャラ<SummonBlue:神王·図鲁>を召喚で獲得できます。\n·期間中、限定SSR覚醒体<SummonBlue:神王·図鲁>の召喚での出現率が増加します。\n·今回の期間限定キャラ召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や命輪は基本確率で取得できます。詳細は【召喚ルール】をご参照ください。\n·毎日のおすすめ召喚：今回の期間限定キャラ召喚では、守秘者は毎日60源液で1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【バランス調整】>\n·ゲームの特性上、公平性を確保するため、覚醒体や命輪の効果を調整する場合があります。\n·効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や命輪の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n·以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_77955_LongDesc2 = {
    Text = "<Title:【SSR】>\n【<SummonBlue:仮テキスト>】期間限定イベントキャラ召喚において、SSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。SSRはすべて覚醒体となり、最大30回の召喚で保証によりSSR覚醒体を必ず獲得できます。\n·覚醒でSSR覚醒体を獲得した場合、33.33%の確率で今期UPのSSR覚醒体<SummonBlue:神王·図鲁>となります。\n·獲得したSSR覚醒体が2回連続で今回ピックアップのキャラでない場合、次の召喚で獲得するSSRは必ず今回ピックアップのキャラになります。{s1}\n·現在、{s2}回連続で、今回ピックアップのキャラではないものを獲得しています。{s3}\n\n<Title:【SR】>\n【<SummonBlue:仮テキスト>】キャラ召喚において、SRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。この召喚のSRはすべて命輪となります。\n·最大5回の召喚で保証によりSR以上を必ず獲得します。保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n·SR命輪を獲得すると、同時に5個の「根源の澱」を副産物として獲得します；R命輪を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n·いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます；17回目以降は非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任意選択方式（原質楽園、返魂のコア、原型視界など）およびランダム方式（原質捕獲·忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は、「根源の澱」には変換されません。\n·この召喚タイプは【イベントキャラ召喚】に該当します。どの【イベントキャラ召喚】でも保証召喚回数は共通して累積されます。他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n\n"
  },
  Summon_77955_Name = {
    Text = "イベントキャラ召喚"
