  },
  Summon_77956_Desc = {
    Text = "<SummonPurple:5>回の召喚ごとにSR以上確定"
  },
  Summon_77956_LongDesc1 = {
    Text = "【<SummonPurple:誘心の医者>】期間限定イベントキャラ召喚が開始しました。\n期間中、守秘者は期間限定キャラ<SummonPurple:クレメンタイン>を召喚で獲得できます。\n·期間中、限定SSR覚醒体<SummonPurple:クレメンタイン>の召喚での出現率が増加します。\n·今回の期間限定キャラ召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は【召喚ルール】をご参照ください。\n·毎日のおすすめ召喚：今回の期間限定キャラ召喚では、守秘者は毎日60プラチナジェルで1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【注意】>\n·ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n·効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n·以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_77956_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:誘心の医者>】の期間限定キャラクターイベント覚醒において、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底によってSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した際、33.33%の確率で今期UPのSSR覚醒体<SummonPurple:クレメンタイン>となります。\n·連続して2回覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回非今期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonPurple:誘心の医者>】のキャラクターイベント覚醒において、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によってSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した際、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した際は、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含む)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合は、非限定SSR覚醒体は【灵魂回溯碎片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【灵魂回溯碎片】×2と【根源の澱】×250に変換されます。ただし、いずれの選択方式(原質楽園、返魂のコア、原型視界などを含む)やランダム方式(原質捕獲·忘却篇などを含む)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
