  Summon_78009_Desc = {
    Text = "<SummonPurple:5>回の召喚ごとにSR以上確定"
  },
  Summon_78009_LongDesc1 = {
    Text = "【<SummonPurple:臨時テキスト>】限定命輪イベント覚醒が開催されました。活動期間中、シークレットキーパーはここから限定イベントUP命輪<SummonPurple:暮星・ティンクト専用武器>を覚醒できます。\n·活動期間中、限定SSR命輪<SummonPurple:暮星・ティンクト専用武器>の覚醒獲得確率がアップします。\n·今回の限定イベント覚醒では、確率アップや天井などの特殊ルールが発動する場合を除き、すべての覚醒体または命輪は基礎確率を使用します。詳細はルール説明に準じます。\n·毎日おすすめ覚醒：今回の限定イベント覚醒では、シークレットキーパーは毎日60プラチナジェルの特別価格で1回覚醒でき、さらにシルバーコア60個が追加で贈呈されます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特殊性により、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体・命輪の効果に対して弱体化または強化のバランス調整を行う場合があります。\n·弱体化が発生した際、ゲームは限定巻き戻し機能を開放し、覚醒体・命輪の育成または覚醒においてリソースを再配置する機会を提供します。\n·この点を理解・承諾した上で、リソースを投入するようにしてください。"
  },
  Summon_78009_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:臨時テキスト>】限定命輪イベント覚醒において、SSRアイテムの基礎確率は3.03%、総合確率（天井含む）は5.02%です。獲得したSSRアイテムはすべて命輪であり、最大30回の覚醒で必ず天井によりSSR命輪を獲得できます。\n·覚醒によりSSR命輪を獲得した際、50.00%の確率で今期UPのSSR命輪<SummonPurple:暮星・ティンクト専用武器>となります。\n·前回の覚醒で獲得したSSR命輪が今期確率アップ命輪でなかった場合、次回覚醒で獲得するSSR命輪は必ず今期確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonPurple:臨時テキスト>】命輪イベント覚醒において、SRアイテムの覚醒基礎確率は15.85%、総合確率（天井含む）は25.00%です。この覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず天井によりSR以上のアイテムを獲得でき、天井でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別説明】>\n·覚醒でSSR命輪を獲得した際、副産物として根源の澱を50個同時に獲得します；SR命輪を獲得した際、副産物として根源の澱を5個同時に獲得します；R命輪を獲得した際、副産物として根源の澱を1個同時に獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれらに限らない）を問わず、同一のSSR命輪を2〜16回目に獲得した場合、毎回自動的に重複位置レベルが上昇し「 根源の澱」×50を獲得します；17回目以降に獲得した場合、「廻命リセットの破片」×1、「 根源の澱」×50、「薔薇金券」×20000に変換され、限定SSR命輪は「廻命リセットの破片」×2、「 根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、廻命のコア等を含む）およびランダム方式（宿命が固定される·忘却篇等を含む）により命輪を獲得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属します。任意の【命輪イベント覚醒】において、天井の覚醒回数は共通で累計され、他の覚醒タイプの天井回数とは独立して計算されます。"
  },
  Summon_78009_Name = {
    Text = "イベント運命の札召喚"
