  Summon_78014_LongDesc1 = {
    Text = "【<SummonOrange:詭眸誘心>】期間限定命輪イベント覚醒が開始しました。期間中、守秘者は期間限定の命輪<SummonOrange:枉蹙眉>を覚醒で獲得できます。\n·期間中、限定SSR命輪<SummonOrange:枉蹙眉>の覚醒での出現率が増加します。\n·今回の期間限定イベント覚醒では、特定の確率増加や保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率で取得できます。詳細はルール説明をご参照ください。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60源液で1回覚醒でき、さらに60銀芯を追加で獲得できます。\n\n<Title:【バランス調整】>\n·ゲームの特性上、公平性を確保するため、覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、期間限定の回溯機能が開放され、覚醒体や命輪の育成や覚醒に必要なリソースを再分配する機会を提供します。\n·以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_78014_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:詭眸誘心>】期間限定命輪イベント覚醒において、SSRアイテムの基本出現率は3.03%、総合出現率（保底込み）は5.02%です。SSRアイテムはすべて命輪となり、最大30回の覚醒で保底によりSSR命輪を必ず獲得できます。\n·覚醒でSSR命輪を獲得した際、50.00%の確率で今期UPのSSR命輪<SummonOrange:枉蹙眉>になります。\n·前回の覚醒で獲得したSSR命輪が今期確率アップの命輪でない場合、次回の覚醒で獲得するSSR命輪は必ず今期確率アップの命輪になります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:詭眸誘心>】命輪イベント覚醒において、SRアイテムの基本出現率は15.85%、総合出現率（保底込み）は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で保底によりSR以上を必ず獲得します。保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特記事項】>\n·覚醒でSSR命輪を獲得すると、同時に50個の「根源の澱」を副産物として獲得します；SR命輪を獲得すると、同時に5個の「根源の澱」を副産物として獲得します；R命輪を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一SSR命輪を2〜16回目に獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；17回目以降に獲得した場合、「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱への変換は行われません。\n·この覚醒タイプは【命輪イベント覚醒】に該当します。どの【命輪イベント覚醒】でも保底覚醒回数は共通して累積されます。他の覚醒タイプのものとは、保底覚醒回数は別個にカウントされます。\n"
  },
