  },
  Summon_78015_LongDesc1 = {
    Text = "【<SummonOrange:回還岐路>】期間限定命輪イベント覚醒が開始しました。イベント期間中、守秘者はその中から期間限定UP命輪<SummonOrange:歪んだ騎士詩>を覚醒で獲得できます。\n·イベント期間中、限定SSR命輪<SummonOrange:歪んだ騎士詩>の覚醒獲得確率が上昇します。\n\n·今回の期間限定イベント覚醒では、確率上昇や保証などの特別ルールを除き、すべての覚醒体または命輪は基本確率が適用されます。詳細はルール説明をご参照ください。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60プラチナジェルでお得に1回覚醒でき、さらに60シルバーコアがプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性により、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒のためにリソースを再配置する機会を提供する期間限定の振り返り機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_78015_LongDesc2 = {
    Text = "<Title:【SSR】>\n【<SummonOrange:回還岐路>】期間限定イベント命輪覚醒において、SSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。SSRはすべて命輪となり、最大30回の覚醒で保証によりSSR命輪を必ず獲得できます。\n·覚醒でSSR命輪を獲得した際、50.00%の確率で今回ピックアップのSSR命輪<SummonOrange:歪んだ騎士詩>となります。\n·前回覚醒で獲得したSSR命輪が今回の確率上昇命輪でない場合、次に覚醒で獲得するSSR命輪は必ず今回の確率上昇命輪になります。\n\n<Title:【SR】>\n【<SummonOrange:回還岐路>】命輪イベント覚醒において、SRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。この覚醒のSRはすべて命輪となります。\n·最大5回の覚醒で保証によりSR以上を必ず獲得します。保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n·覚醒でSSR命輪を獲得すると、同時に50個の「根源の澱」を副産物として獲得します。SR命輪を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。R命輪を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）で同一SSR命輪を2〜16回目に獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します。17回目以降の獲得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯のコア等を含む）および、ランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【イベント命輪覚醒】に該当します。どの【イベント命輪覚醒】でも保証覚醒回数は共通して累積され、他の覚醒タイプの保証覚醒回数とは別個にカウントされます。\n"
