  Summon_78016_Title = {
    Text = "遺落孤島"
  },
  Summon_78017_Desc = {
    Text = "<SummonPurple:5>回の召喚ごとにSR以上確定"
  },
  Summon_78017_LongDesc1 = {
    Text = "【<SummonPurple:亘古罗网>】期間限定イベント運命の札召喚が開始しました。\n期間中、守秘者は期間限定の運命の札<SummonPurple:永世編織之網>を召喚で獲得できます。\n\n・期間中、限定SSR運命の札<SummonPurple:永世編織之網>の召喚での出現率が増加します。\n\n・今回の期間限定の運命の札召喚では、特定の確率増加や保証などの特別ルールを除き、すべての覚醒体や運命の札は基本確率で取得できます。詳細は【召喚ルール】をご参照ください。\n\n・毎日のおすすめ召喚：今回の期間限定の運命の札召喚では、守秘者は毎日60プラチナジェルで1回召喚でき、さらに60シルバーコアを追加で獲得できます。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。\n\n"
  },
  Summon_78017_LongDesc2 = {
    Text = "<Title:【SSR】>\n・【<SummonPurple:亘古罗网>】期間限定イベント運命の札召喚において、\nSSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。\nSSRはすべて運命の札となり、最大30回の召喚で保証によりSSR運命の札を必ず獲得できます。\n・召喚でSSR運命の札を獲得した際、50.00%の確率で今回ピックアップのSSR運命の札<SummonPurple:永世編織之網>となります。\n・前回獲得したSSR運命の札が今回の確率アップ対象でない場合、次の召喚で獲得するSSR運命の札は必ず今回の確率アップ対象の運命の札になります。\n\n<Title:【SR】>\n・【<SummonPurple:亘古罗网>】運命の札召喚において、\nSRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。\nこの召喚のSRはすべて運命の札となります。\n\n・最大5回の召喚で保証によりSR以上を必ず獲得します。\n保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n・SSR運命の札を獲得すると、同時に50個の「根源の澱」を副産物として獲得します。\n・SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。\n・R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n・いかなる方法（召喚、ショップ交換、システム配布等を含むがこれに限らない）であっても、同一のSSR運命の札を2〜16回目に獲得した場合、毎回自動的に重ね段階がアップし「根源の澱」×50を獲得します。17回目以降の獲得は「運命回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR運命の札は「運命回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、運命回溯のコア等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で運命の札を獲得した場合、根源の澱への変換は行われません。\n・この召喚タイプは【イベント運命の札召喚】に該当します。\nどの【イベント運命の札召喚】でも保証召喚回数は共通して累積されます。\n他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n"
  },
