  Summon_78024_Title = {
    Text = "苦痛の追憶"
  },
  Summon_78811_Desc = {
    Text = "毎回<SummonOrange:5>回の覚醒で必ずSR級以上の命輪が出現する"
  },
  Summon_78811_LongDesc1 = {
    Text = "【<SummonOrange:虚無投影>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者はここから期間限定UP命輪<SummonOrange:虚無に墜ちた人形>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:虚無に墜ちた人形>の覚醒取得確率がアップします。\n\n·今回の期間限定イベント覚醒では、確率アップや保障などの特別ルールを除き、すべての覚醒体または命輪は基本確率を使用し、具体的にはルール説明に従います。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドで一回の覚醒をお得に行うことができ、さらに60シルバーコアがプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームのプレイスタイルが特別であるため、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは限時回溯機能を開放し、覚醒体や命輪の育成または覚醒に再配置リソースの機会を提供します。\n·必ずこれを理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_78811_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:虚無投影>】の期間限定命輪イベント覚醒中、SSRアイテムを獲得する基本確率は3.03％、総合確率(保底含む)は5.02％です。獲得したSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底でSSR命輪を獲得できます。\n·覚醒でSSR命輪を獲得した場合、本期UPのSSR命輪<SummonOrange:虚無に墜ちる人形>である確率は50.00％です。\n·前回の覚醒で獲得したSSR命輪が本期確率アップ命輪でない場合、次回の覚醒で獲得するSSR命輪は必ず本期確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:虚無投影>】の命輪イベント覚醒中、SRアイテムの覚醒基本確率は15.85％、総合確率(保底含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底でSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を獲得した場合、同時に50個の根源の澱を副産物として獲得します；SR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の獲得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱は変換されません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において、保底覚醒回数が共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
