  Summon_78811_Title = {
    Text = "虚無投影"
  },
  Summon_78814_Desc = {
    Text = "毎 <SummonRed:5> 回の覚醒で必ずSR級以上の対象が出現します"
  },
  Summon_78814_LongDesc1 = {
    Text = "【<SummonRed:復讐の獣>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UPキャラクター<SummonRed:ブラッドチェーン・ヘロット>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonRed:ブラッドチェーン・ヘロット>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonRed:ブラッドチェーン・ヘロット>は初回UP後3ヶ月から9ヶ月の間に期間限定キャラクターイベント覚醒に登場し、約1年後に【界域研習】常駐キャラクター覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率アップ、保底などの特別ルールの発動を除き、すべての覚醒体や命輪は基本確率が適用され、具体的な内容はルール説明に従います。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドで1回の覚醒を行うことができ、さらに60シルバーコアが贈呈されます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再配置資源の機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上で資源を投入してください。\n\n"
  },
  Summon_78814_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonRed:復讐の獣>】期間限定キャラクターイベント覚醒中、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムはすべて覚醒体で、最大30回の覚醒で必ず保底でSSR覚醒体を獲得できます。\n·覚醒によってSSR覚醒体を獲得する際、33.33%の確率で今期UPのSSR覚醒体<SummonRed:血鎖・ヘロット>となります。\n·連続して2回覚醒で獲得したSSR覚醒体が今期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず今期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回今期UPキャラクター以外を獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonRed:復讐の獣>】キャラクターイベント覚醒中、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底でSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得する際、同時に5個の根源の澱を副産物として得られます；R命輪を獲得する際、同時に1個の根源の澱を副産物として得られます。\n·いかなる方法(覚醒、ショップ交換、システムプレゼントなどを含む)で第2〜16回目に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回目以降の獲得では、非限定SSR覚醒体は【魂溯の欠片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【魂溯の欠片】×2と【根源の澱】×250に変換されます。しかし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
