  Summon_78826_LongDesc1 = {
    Text = "【<SummonOrange:赤い雨が降り注ぐ>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者は限定イベントUP命輪<SummonOrange:深紅に沈む>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:深紅に沈む>の覚醒取得確率がアップします。\n·イベント終了後、限定SSR命輪<SummonOrange:深紅に沈む>は初回UP後3〜9ヶ月の期間限定命輪イベント覚醒に引き続き登場し、約1年後に【輪転の相】常駐命輪覚醒に移行します。\n·今回の期間限定イベント覚醒では、確率アップや保底などの特別ルールが発生しない限り、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に基づきます。\n·毎日のおすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドで1回の覚醒をお得に行い、さらに60シルバーコアをプレゼントします。\n\n<Title:【バランス調整】>\n·ゲームのプレイスタイルが特異なため、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒のためにリソースを再配置する機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_78826_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:赤い雨が降り注ぐ>】期間限定命輪イベント覚醒中、SSRアイテムの基本確率は3.03％、総合確率(保障含む)は5.02％です。取得したSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保障によりSSR命輪を獲得できます。\n·覚醒でSSR命輪を取得した場合、50.00％の確率で今期UPのSSR命輪<SummonOrange:深紅に沈む>となります。\n·前回の覚醒で取得したSSR命輪が今期の確率アップ命輪でない場合、次回の覚醒で取得するSSR命輪は必ず今期の確率アップ命輪となります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:赤い雨が降り注ぐ>】命輪イベント覚醒中、SRアイテム覚醒の基本確率は15.85％、総合確率(保障含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保障によりSR以上のアイテムを獲得でき、保障でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を獲得した場合、同時に50個の根源の澱を副産物として獲得します；SR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の獲得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱は変換されません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】で、保障覚醒回数は共通して累積され、他の覚醒タイプの保障覚醒回数とは独立して統計されます。\n"
  },
