  Summon_78826_Title = {
    Text = "赤い雨が降り注ぐ"
  },
  Summon_81451_Desc = {
    Text = "召喚結果を変えたい場合は何度でも再召喚可能"
  },
  Summon_81451_LongDesc1 = {
    Text = "【初回限定無料召喚】新任用・全界域キャラ召喚では、希望の覚醒体を獲得するまで、無限に召喚を行うことができます。\n\n・【初回限定無料召喚】では召喚結果を確定するまで何度でも無料で再召喚が可能です。\n・【初回限定無料召喚】では5回連続の抽選で、必ずランダムに1つの常設SSR覚醒体が獲得できます。\n\n・召喚結果を確定すると、【初回限定無料召喚】は閉じられます。\n・すべての運命の札は基本確率で取得できます。詳細は「召喚ルール」をご参照ください。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化されます場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。"
  },
  Summon_81451_LongDesc2 = {
    Text = "<Title:【SSR】>\n・【銀輝初耀】新人キャラ召喚において、\nSSRの総合出現率は20%です。\nSSRはすべて覚醒体となり、最大5回の召喚で必ず保証によりSSR覚醒体を獲得できます。\n\n<Title:【SR】>\n・【銀輝初耀】新人キャラ召喚において、\nSRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。\nこの召喚のSRはすべて運命の札となります。\n\n<Title:【特記事項】>\n・SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。\n・R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n\n・いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます。\n\n・17回目以降は常設（非限定）SSR覚醒体は「魂の回溯の欠片」×1と「根源の澱」×150に変換されます。限定SSR覚醒体は「魂の回溯の欠片」×2と「根源の澱」×250に変換されます。\nただし、任意選択方式（魔封瓶、返魂のコア、精神体カプセルなど）およびランダム方式（根源の捕獲・忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は、「根源の澱」には変換されません。"
  },
  Summon_81451_Name = {
    Text = "新任用・全界域キャラ召喚"
  },
  Summon_81451_RateListTextSR = {
    Text = "召喚1～4回の総合出現率："
  },
  Summon_81451_RateListTextSSR = {
    Text = "召喚5回毎の総合出現率："
  },
  Summon_81451_ShortDesc = {
    Text = "初回の<color=#f0d67b>5</color>回連続召喚で必ず SSR覚醒体を獲得"
  },
  Summon_81451_Title = {
    Text = "初回限定無料召喚"
  },
  Summon_81492_Desc = {
    Text = "毎<{s1}:5>回の覚醒でSR級以上の対象が必ず出ます"
  },
  Summon_81492_LongDesc1 = {
    Text = "【<SummonOrange:古の呼び出し>】期間限定イベントの覚醒が開始されました。イベント期間中、守秘者は<SummonOrange:自由選定>の覚醒体と推奨命輪から取得確率がアップします。\n·【古の呼び出し】順序命理で指定の覚醒体を覚醒した後、覚醒を通じて覚醒体と命輪を取得でき、覚醒体を得た場合、必ず選択した覚醒体の界域の覚醒体となります。\n\n·イベント期間中、選択した<SummonOrange:SSR覚醒体と推奨命輪>の覚醒取得確率がアップします。\n·今回の期間限定イベントの覚醒では、触発確率アップ、保底などの特殊ルールを除き、すべての覚醒体または命輪は基本確率を使用し、具体的にはルール説明に従います。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再配置リソースの機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_81492_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:古の呼び出し>】の期間限定イベント覚醒中、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得されるSSRアイテムは覚醒体または命輪で、最大30回の覚醒で必ず保底によりSSR覚醒体または推奨命輪を獲得できます。\n·覚醒でSSRを獲得した場合、33.33%の確率で今期選定のSSR<SummonOrange:覚醒体または推奨命輪>となります。\n·連続して2回の覚醒で獲得したSSRが今期選定のSSR覚醒体または命輪でない場合、次回の覚醒で獲得するSSRは必ず今期選定のSSR覚醒体または命輪となります。{s1}\n·現在、{s2}回連続で今期選定の覚醒体または命輪でないものを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonOrange:古の呼び出し>】イベント覚醒中、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別説明】>\n·覚醒でSSR命輪を獲得した場合、同時に50個の根源の澱を副産物として獲得します；覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は【灵魂回溯碎片】×1と【根源の澱】×150に変換され、限定SSR覚醒体は【灵魂回溯碎片】×2と【根源の澱】×250に変換されます。しかし、任意選択方式(原質楽園、返魂のコア、原型視界などを含む)やランダム方式(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【順序命理】に属し、任意の【順序命理】内で保底覚醒回数は共同累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
