  Summon_81536_LongDesc1 = {
    Text = "【<SummonBlue:忘れられていない·深海>】運命の軌道連合覚醒が開始されました。イベント期間中、守秘者は2体のランダムSSR覚醒体と3個のランダムSSR命輪を呼び出すことができます。\n·各運命の軌道連合覚醒は、5回の覚醒後に終了します。\n·今回の運命の軌道連合覚醒イベントでは、毎回の覚醒で必ずランダムSSR覚醒体とランダムSSR命輪を獲得できます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するため、覚醒体や命輪の効果に対して弱体化または強化のバランス調整が行われる場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒にリソースを再配置する機会を提供するために、期間限定の巻き戻し機能を開放します。\n·この点を理解し、受け入れた上でリソースの投入を行ってください。\n\n<Title:【期間限定ミッション】>\n·イベント期間中、初めて運命の軌道連合覚醒を完了すると、期間限定ミッションが達成され、「スキンデザインクーポン(一期)」*1を獲得できます！\n·5月26日9:00 - 6月9日9:00(GMT+8)の間、「ショップ：幻衣の注文」で「スキンデザインクーポン(一期)」を使用してシンプルなファンタジー衣装と交換できます。\n·「スキンデザインクーポン(一期)」の入手方法については、コミュニティやお知らせをご覧ください。\n\n"
  },
  Summon_81536_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonBlue:忘れられていない·深海>】の運命の軌道連合覚醒において、SSRアイテムの総合確率は100.00%です。取得できるSSRアイテムは、2体の覚醒体と3つの命輪です。\n·覚醒を通じてSSR覚醒体を取得した際、100%の確率で<SummonBlue:深海>境界の覚醒体となります。\n\n<Title:【特別な説明】>\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回目に同じSSR覚醒体を取得した場合、毎回1つの対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回目以降は、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任選方式(原質楽園、灵魂回溯之芯、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を取得した場合、根源の澱には変換されません。"
  },
