  },
  Summon_81537_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonRed:忘れられていない·血肉>】命の軌道連合覚醒において、SSRアイテムを取得する総合確率は100.00%です。取得されるSSRアイテムは2つの覚醒体と3つの命輪です。\n·覚醒によってSSR覚醒体を取得した場合、100%の確率で<SummonRed:血肉>界域の覚醒体となります。\n\n<Title:【特別な説明】>\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)であっても、2回目から16回目まで同じSSR覚醒体を取得した場合、毎回1つの対応する覚醒体の欠片と50個の根源の澱に変換されます。17回目以降の取得では、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任選方式(原質楽園、灵魂回溯之芯、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を取得した場合、根源の澱には変換されません。"
