  Summon_81539_LongDesc1 = {
    Text = "【<SummonOrange:忘れられていない·混沌>】運命の軌道連合覚醒が開始されました。活動期間中、守秘者は2体のランダムSSR覚醒体と3つのランダムSSR命輪を覚醒させることができます。\n·各運命の軌道連合覚醒は5回の覚醒後に終了します。\n·今回の運命の軌道連合覚醒イベントでは、毎回の覚醒で必ずランダムSSR覚醒体とランダムSSR命輪を獲得できます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、覚醒体や命輪の効果に対するバランス調整が行われる可能性があります。\n·削弱が発生した場合、ゲームは限時回溯機能を開放し、覚醒体や命輪の育成または覚醒に再配置リソースの機会を提供します。\n·この点を理解し、受け入れた上でリソースの投入を行ってください。\n\n<Title:【限時任務】>\n·活動期間中、初めて運命の軌道連合覚醒を完了すると、限時任務が達成され、「スキンデザインクーポン(一期)」*1を獲得できます！\n·5月26日9:00 - 6月9日9:00(GMT+8)の期間中、「ショップ：幻衣の注文」で「スキンデザインクーポン(一期)」を使用してシンプルなファンタジー衣装を交換できます。\n·「スキンデザインクーポン(一期)」の取得方法については、コミュニティやお知らせでご確認ください。\n\n"
  },
  Summon_81539_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:忘れられていない·混沌>】運命の軌道連合覚醒において、SSRアイテムの総合確率は100.00%です。獲得するSSRアイテムは2つの覚醒体と3つの命輪です。\n·覚醒によってSSR覚醒体を取得した場合、100%の確率で<SummonOrange:混沌>界域の覚醒体となります。\n\n<Title:【特別な説明】>\n·どのような方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回目に同じSSR覚醒体を獲得した場合、毎回対応する覚醒体の欠片1個と根源の澱50個に変換されます；第17回目以降の獲得では、非限定SSR覚醒体は「魂の回溯の欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「魂の回溯の欠片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、精神体カプセルなどを含む)やランダムな方法(原質キャプチャ·忘却篇などを含む)で覚醒体または溢れた覚醒体の欠片を取得した場合、根源の澱には変換されません。"
  },
  Summon_81539_Name = {
