  Summon_81539_ProbabilityUpDesc = {
    Text = "「忘却篇」<SummonOrange:混沌>境域覚醒"
  },
  Summon_81539_RateListTextSSR = {
    Text = "SSRアイテムの保底総合出率：100.00%"
  },
  Summon_81539_ShortDesc = {
    Text = "必ず <SummonOrange:2> 個の限定覚醒体と <SummonOrange:3> 個の限定命輪を得る"
