  Summon_81539_Title = {
    Text = "忘れられなかった·混沌"
  },
  Summon_89883_Desc = {
    Text = "毎<SummonOrange:5>回の覚醒でSR以上の対象が必ず出現"
  },
  Summon_89883_LongDesc1 = {
    Text = "【<SummonOrange:千幕の旅>】すべての生命の百相の覚醒が開始されました。イベント期間中、守秘者はすべての界域の一部限定SSR覚醒体と一部限定SSR命輪を呼び出すことができます。\n·今回の期間限定イベントの覚醒では、トリガー確率の上昇や保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に従います。\n·毎日の推薦覚醒：今回のすべての生命の百相の覚醒中、守秘者は毎日60ソースリキッドでお得に1回覚醒でき、さらに60シルバーコアがプレゼントされます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒にリソースを再配置する機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_89883_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n·【<SummonOrange:千幕の旅>】すべての生命の百相を覚醒させる中で、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底を含む)は5.02%です。獲得したSSRアイテムは覚醒体または命輪で、最大30回の覚醒で必ず保底でSSR覚醒体または命輪を獲得できます。\n·覚醒でSSRアイテムを獲得した場合、33.33%の確率でSSR覚醒体となります。\n·連続して2回覚醒で獲得したSSRが命輪の場合、次回の覚醒で獲得するSSRは必ず覚醒体となります。{s1}\n·現在、連続{s2}回非SSR覚醒体を獲得しています。{s3}\n\n<Title:【SRアイテム】>\n·【<SummonOrange:千幕の旅>】キャラクターイベント覚醒中で、SRアイテムを獲得する基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底でSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を獲得した場合、同時に50個の根源の澱を副産物として獲得します；覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回に同じSSR命輪を獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降に獲得した場合、「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。第2〜16回に同じSSR覚醒体を獲得した場合、毎回1個の対応する覚醒体の残片と50個の根源の澱に変換されます；第17回以降に獲得した場合、非限定SSR覚醒体は「灵魂回溯の欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯の欠片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または余剰覚醒体の残片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【すべての生命の百相を覚醒させる】に属し、任意の【すべての生命の百相を覚醒させる】中で、保底覚醒回数は共同累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
