  Summon_89883_Title = {
    Text = "千幕の旅"
  },
  Summon_91398_Desc = {
    Text = "同一のピックアップの取得は連続<{s1}:2>回まで"
  },
  Summon_91398_LongDesc1 = {
    Text = "【<SummonOrange:古の呼び出し>】期間限定イベントの覚醒が開始されました。イベント期間中、守秘者は<SummonOrange:自由選定>の覚醒体と推奨命輪から取得確率がアップします。\n·【古の呼び出し】順序命理で指定の覚醒体を覚醒した後、覚醒を通じて覚醒体と命輪を取得でき、覚醒体を得た場合、必ず選択した覚醒体の界域の覚醒体となります。\n\n·イベント期間中、選択した<SummonOrange:SSR覚醒体と推奨命輪>の覚醒取得確率がアップします。\n·今回の期間限定イベントの覚醒では、触発確率アップ、保底などの特殊ルールを除き、すべての覚醒体または命輪は基本確率を使用し、具体的にはルール説明に従います。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再配置リソースの機会を提供するために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_91398_LongDesc2 = {
    Text = "<Title:【SSR】>\n·【<SummonOrange:久遠の呼び声>】期間限定運命の選択召喚において、\nSSRの基本出現率は3.03%、総合出現率（保証込み）は5.02%です。\nSSRは覚醒体もしくは運命の札となり、最大30回の召喚で保証によりSSR覚醒体もしくはSSR運命の札を必ず獲得できます。\n·覚醒でSSRを獲得した場合、33.33%の確率で今期選定のSSR<SummonOrange:覚醒体または推奨命輪>となります。\n·連続して2回の覚醒で獲得したSSRが今期選定のSSR覚醒体または命輪でない場合、次回の覚醒で獲得するSSRは必ず今期選定のSSR覚醒体または命輪となります。{s1}\n·現在、{s2}回連続で、今回ピックアップのキャラではないものを獲得しています。{s3}\n·出現率UP中の内容の内、同じ覚醒体または運命の札を2回連続で取得した場合、次に出現率UP中の内容を取得する際は必ずもう一方の覚醒体または運命の札となります。\n·現在、連続して{s4}回同一の今期UPアイテムを取得しています。\n\n<Title:【SR】>\n·【<SummonOrange:久遠の呼び声>】期間限定運命の選択召喚において、\nSRの基本出現率は15.85%、総合出現率（保証込み）は25.00%です。\nこの召喚のSRはすべて運命の札となります。\n\n·最大5回の召喚で保証によりSR以上を必ず獲得します。\n保証の際、SRの出現率は96.97%、SSRの出現率は3.03%です。\n\n<Title:【特記事項】>\n·SSR運命の札を獲得すると、同時に50個の「根源の澱」を副産物として獲得します。\n·SR運命の札を獲得すると、同時に5個の「根源の澱」を副産物として獲得します。\n·R運命の札を獲得すると、同時に1個の「根源の澱」を副産物として獲得します。\n·いずれの方法（召喚、商店交換、システム贈与などを含むがこれに限らない）でも、2～16回目に同じSSR覚醒体を獲得した場合、対象の「覚醒体の欠片」1個と「根源の澱」50個に変換されます；17回目以降は非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。\nただし、任意選択方式（原質楽園、返魂のコア、原型視界など）およびランダム方式（原質捕獲·忘却篇など）で覚醒体または超過の「覚醒体の欠片」を獲得した場合は、「根源の澱」には変換されません。\n\n·この召喚タイプは【運命の選択召喚】に該当します。\nどの【運命の選択召喚】でも保証召喚回数は共通して累積されます。\n他の召喚タイプのものとは、保証召喚回数は別個にカウントされます。\n\n"
  },
  Summon_91398_Name = {
    Text = "運命の選択召喚"
  },
  Summon_91398_ProbabilityUpDesc = {
    Text = "<{s1}:「{s2}」「{s3}」>\n取得確率アップ"
  },
  Summon_91398_RateListTextR = {
