  Summon_94432_LongDesc1 = {
    Text = "【<SummonOrange:仮テキスト>】期間限定の命輪イベント覚醒が開始されました。イベント期間中、守秘者はその中から期間限定UP命輪<SummonOrange:起源オジール専武>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:起源オジール専武>の覚醒獲得確率が上昇します。\n·今回の期間限定イベント覚醒では、確率上昇や保底などの特別ルールが発動しない限り、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に準じます。\n·毎日おすすめ覚醒：今回の期間限定イベント覚醒では、守秘者は毎日60ソースリキッドの割引で1回覚醒でき、さらに60シルバーコアをプレゼントします。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再配置リソースの機会を与えるために、期間限定の回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースの投入を行ってください。\n\n"
  },
  Summon_94432_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:一時的なテキスト>】の期間限定命輪イベント覚醒において、SSRアイテムの基本確率は3.03%、総合確率(保底を含む)は5.02%です。取得したSSRアイテムは全て命輪で、最大30回の覚醒で必ず保底によってSSR命輪を取得できます。\n·覚醒でSSR命輪を取得した際、本期UPのSSR命輪<SummonOrange:本源オジール専武>である確率は50.00%です。\n·前回の覚醒で取得したSSR命輪が本期確率アップ命輪でない場合、次回の覚醒で取得するSSR命輪は必ず本期確率アップ命輪になります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:一時的なテキスト>】の命輪イベント覚醒において、SRアイテムの覚醒基本確率は15.85%、総合確率(保底を含む)は25.00%です。本覚醒内のSRアイテムは全て命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97%、SSRアイテムを取得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を取得した際、同時に50個の根源の澱を副産物として取得します；SR命輪を取得した際、同時に5個の根源の澱を副産物として取得します；R命輪を取得した際、同時に1個の根源の澱を副産物として取得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一SSR命輪を2〜16回目に取得した際、毎回自動的に重ね段階が上昇し「根源の澱」×50を獲得します；17回目以降の取得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換され、限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし任意選択方式（輪転の書、命途回溯の芯等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を取得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
