  Summon_97299_LongDesc1 = {
    Text = "【<SummonRed:慈母邂逅>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定イベントUPキャラクター<SummonRed:タイス>を覚醒させることができます。\n·イベント期間中、限定SSR覚醒体<SummonRed:タイス>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonRed:タイス>は初回UP後3ヶ月から9ヶ月の期間限定キャラクターイベント覚醒に引き続き登場しますが、約1年後に【界域研習】常駐キャラクター覚醒に移行します。\n·今回の期間限定イベント覚醒では、触発確率上昇や保底などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用します。具体的な内容はルール説明に従ってください。\n\n<Title:【バランス調整】>\n·ゲームのプレイスタイルに特有のため、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成または覚醒に再配置リソースの機会を提供するための期間限定回溯機能を開放します。\n·必ずこの点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
