  Summon_97303_RateListTextSSR = {
    Text = "SSR基本出現率：3.03%<color=#A3A6AB>（保証込み総合出現率：5.02%）</color>"
  },
  Summon_97303_ShortDesc = {
    Text = "獲得覚醒体は必ず<SummonBlue:深海>境界です"
  },
  Summon_97303_Title = {
    Text = "深淵降誕"
  },
  Summon_97304_Desc = {
    Text = "毎回<SummonOrange:5>回の覚醒で必ずSR級以上の命輪が出現する"
  },
  Summon_97304_LongDesc1 = {
    Text = "【<SummonOrange:声の饗宴>】期間限定命輪イベント覚醒が開始されました。イベント期間中、守秘者はこの中から期間限定UP命輪<SummonOrange:女王の戒律>を覚醒させることができます。\n·イベント期間中、限定SSR命輪<SummonOrange:女王の戒律>の覚醒取得確率がアップします。\n·イベント終了後、限定SSR命輪<SummonOrange:女王の戒律>は、初回UP後3 - 9ヶ月の期間限定命輪イベント覚醒に引き続き登場し、約1年後に【輪転の相】常駐命輪覚醒に移行します。\n·今回の期間限定イベント覚醒では、触発確率アップ、保底などの特別ルール以外は、すべての覚醒体または命輪は基本確率を使用し、具体的な内容はルール説明に準じます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性上、ゲームの楽しさと公平性を確保するために、ゲームは覚醒体や命輪の効果に対して弱体化または強化のバランス調整を行うことがあります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再配置リソースの機会を提供するために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_97304_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonOrange:声の饗宴>】の期間限定命輪イベント覚醒中、SSRアイテムを獲得する基本確率は3.03%、総合確率(保底含む)は5.02%です。獲得するSSRアイテムはすべて命輪で、最大30回の覚醒で必ず保底によりSSR命輪を入手できます。\n·覚醒でSSR命輪を獲得した場合、50.00%の確率で今期UPのSSR命輪<SummonOrange:女王の戒律>になります。\n·前回の覚醒で獲得したSSR命輪が今期の確率アップ命輪でない場合、次回の覚醒で獲得するSSR命輪は必ず今期の確率アップ命輪になります。\n\n<Title:【SRアイテム】>\n【<SummonOrange:声の饗宴>】の命輪イベント覚醒中、SRアイテム覚醒の基本確率は15.85%、総合確率(保底含む)は25.00%です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97%、SSRアイテムを獲得する確率は3.03%です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を獲得した場合、同時に50個の根源の澱を副産物として獲得します；SR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法（覚醒、ショップ交換、システム贈呈等を含むがこれに限らない）であっても、同一のSSR命輪を第2〜16回獲得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降の獲得は「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。ただし、任意選択方式（輪転の書、命途回溯のコア等を含む）およびランダム方式（宿命定格·忘却篇等を含む）で命輪を獲得した場合、根源の澱への変換は行われません。\n·今回の覚醒は【命輪イベント覚醒】に属し、任意の【命輪イベント覚醒】において保底の覚醒回数は合算され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n"
  },
  Summon_97304_Name = {
    Text = "命輪イベント覚醒"
  },
  Summon_97304_ProbabilityUpDesc = {
    Text = "<SummonOrange:「女王の戒律」>取得確率上昇！"
  },
  Summon_97304_RateListTextR = {
    Text = "R基本出現率：81.12%<color=#A3A6AB>（保証込み総合出現率：69.98%）</color>"
