  Summon_97304_Title = {
    Text = "声の饗宴"
  },
  Summon_97984_Desc = {
    Text = "期間限定！<SummonPurple:5>回のみ召喚可能！"
  },
  Summon_97984_LongDesc1 = {
    Text = "【<SummonPurple:過ぎし日々の彼方・超次元>】覚醒体・運命の札セット召喚は序章を初回クリア後に開放され、60日間継続します。期間中、守秘者は「忘却篇」のランダムなSSR覚醒体を2体、ランダムなSSR運命の札を3枚獲得できます。\n・この覚醒体・運命の札セット召喚は5回の召喚後に終了します。\n・今回の覚醒体・運命の札セット召喚では、各召喚で必ずランダムなSSR覚醒体またはランダムなSSR運命の札を獲得できます。\n\n<Title:【注意】>\n・ゲームの特性上、公平性を確保するため、覚醒体や運命の札の効果を調整する場合があります。\n・効果が弱化される場合、期間限定のリセット機能が開放され、覚醒体や運命の札の育成や覚醒に必要なリソースを再分配する機会を提供する場合があります。\n・以上の点ご理解、ご了承の上、リソース投入を行っていただくようお願いいたします。"
  },
  Summon_97984_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:往事失落以前·超次元>】運命の軌道連合覚醒において、SSRアイテムを獲得する総合確率は100.00%です。獲得したSSRアイテムは2つの覚醒体と3つの命輪です。\n·覚醒を通じてSSR覚醒体を獲得した場合、100%の確率で<SummonPurple:超次元>界域の覚醒体となります。\n\n<Title:【特別な説明】>\n·いかなる方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回目に同じSSR覚醒体を獲得した場合、毎回対応する覚醒体の欠片1つと根源の澱50個に変換されます；第17回目以降に獲得した場合、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。ただし、任選方式(原質楽園、灵魂回溯之芯、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。"
  },
