  },
  Summon_98111_LongDesc1 = {
    Text = "【<SummonOrange:千幕の旅>】すべての生命の百相の覚醒が開始されました。イベント期間中、守秘者はすべての忘却篇の限定覚醒体と限定命輪を覚醒させることができます。\n·今回の期間限定イベントの覚醒では、触発確率のアップや保底などの特別ルールを除いて、すべての覚醒体または命輪は基本確率を使用し、具体的なルール説明に従います。\n·毎日のおすすめ覚醒：今回のすべての生命の百相の覚醒で、守秘者は毎日60源液の割引で1回覚醒でき、さらに60シルバーコアが贈呈されます。\n\n<Title:【バランス調整】>\n·ゲームのプレイスタイルが特殊であるため、ゲームの楽しさと公平性を確保する観点から、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う可能性があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒に再配置リソースの機会を提供するための期間限定の回溯機能を開放します。\n·必ずこれを理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_98111_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n·【<SummonOrange:千幕の旅>】すべての生命の百相を覚醒させる中で、SSRアイテムを取得する基本確率は3.03％、総合確率(保底を含む)は5.02％です。取得したSSRアイテムは覚醒体または命輪で、最大30回の覚醒で必ず保底によりSSR覚醒体または命輪を取得できます。\n·覚醒でSSRアイテムを取得した場合、33.33％の確率でSSR覚醒体となります。\n·連続して2回覚醒で取得したSSRが命輪の場合、次回の覚醒で取得するSSRは必ず覚醒体となります。\n·連続して2回覚醒で取得したSSRが覚醒体の場合、次回の覚醒で取得するSSRは必ず命輪となります。{s1}\n·現在、連続{s2}回SSR覚醒体を獲得しています。{s3}\n·現在、連続{s4}回SSR命輪を獲得しています。{s3}\n\n<Title:【SRアイテム】>\n·【<SummonOrange:千幕の旅>】キャラクターイベント覚醒中で、SRアイテムを取得する基本確率は15.85％、総合確率(保底を含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを取得でき、保底でSRアイテムを取得する確率は96.97％、SSRアイテムを取得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSSR命輪を取得した場合、同時に50個の根源の澱を副産物として獲得します；覚醒でSR命輪を取得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を取得した場合、同時に1個の根源の澱を副産物として獲得します。\n·どの方法(覚醒、ショップ交換、システム贈呈などを含むがこれに限らない)で第2〜16回に同じSSR命輪を取得した場合、毎回自動的に重ね位レベルが上昇し「根源の澱」×50を獲得します；第17回以降に取得した場合、「命途回溯の欠片」×1、「根源の澱」×50、「薔薇金券」×20000に変換されます。限定SSR命輪は「命途回溯の欠片」×2、「根源の澱」×50、「薔薇金券」×20000に変換されます。第2〜16回に同じSSR覚醒体を取得した場合、毎回対応する覚醒体の残片1個と根源の澱50個に変換されます；第17回以降に取得した場合、非限定SSR覚醒体は「灵魂回溯の欠片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯の欠片」×2と「根源の澱」×250に変換されます。ただし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢出覚醒体の残片を取得した場合、根源の澱には変換されません。\n·今回の覚醒は【すべての生命の百相を覚醒させる】に属し、任意の【すべての生命の百相を覚醒させる】の中で、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
  Summon_98111_Name = {
    Text = "すべての生命の百相を覚醒させる"
  },
  Summon_98111_ProbabilityUpDesc = {
    Text = "SSRは必ず忘却篇<SummonOrange:限定>です！"
  },
  Summon_98111_RateListTextR = {
    Text = "R基本出現率：81.12%<color=#A3A6AB>（保証込み総合出現率：69.98%）</color>"
