  Summon_98327_LongDesc1 = {
    Text = "【<SummonPurple:紙が灰になる>】期間限定キャラクターイベント覚醒が開始されました。イベント期間中、守秘者は期間限定UPキャラクター<SummonPurple:オルラ>を覚醒できます。\n·イベント期間中、限定SSR覚醒体<SummonPurple:オルラ>の覚醒獲得確率が上昇します。\n·イベント終了後、限定SSR覚醒体<SummonPurple:オルラ>は、初回UP後3ヶ月から9ヶ月の期間限定キャラクターイベント覚醒に引き続き登場し、約1年後に【界域研習】常駐キャラクター覚醒に入ります。\n·今回の期間限定イベント覚醒では、確率上昇や保障などの特別ルールを除き、すべての覚醒体や命輪は基本確率を使用し、具体的にはルール説明に準じます。\n\n<Title:【バランス調整】>\n·ゲームプレイの特性により、ゲームの楽しさと公平性を確保するため、ゲームは覚醒体や命輪の効果を弱体化または強化するバランス調整を行う場合があります。\n·弱体化が発生した場合、ゲームは覚醒体や命輪の育成や覚醒においてリソースを再配置する機会を提供するために、期間限定の回溯機能を開放します。\n·この点を理解し、受け入れた上でリソースを投入してください。\n\n"
  },
  Summon_98327_LongDesc2 = {
    Text = "<Title:【SSRアイテム】>\n【<SummonPurple:紙が灰になる>】の期間限定キャラクターイベント覚醒中に、SSRアイテムを獲得する基本確率は3.03％、総合確率(保底含む)は5.02％です。獲得したSSRアイテムはすべて覚醒体であり、最大30回の覚醒で必ず保底によりSSR覚醒体を獲得できます。\n·覚醒でSSR覚醒体を獲得した際、本期UPのSSR覚醒体<SummonPurple:オルラ>である確率は33.33％です。\n·連続して2回の覚醒で獲得したSSR覚醒体が本期確率アップキャラクターでない場合、次回の覚醒で獲得するSSRキャラクターは必ず本期確率アップキャラクターとなります。{s1}\n·現在、連続{s2}回非本期UPキャラクターを獲得しています。{s3}\n\n<Title:【SRアイテム】>\n【<SummonPurple:紙が灰になる>】のキャラクターイベント覚醒中に、SRアイテムを獲得する基本確率は15.85％、総合確率(保底含む)は25.00％です。本覚醒内のSRアイテムはすべて命輪です。\n·最大5回の覚醒で必ず保底によりSR以上のアイテムを獲得でき、保底でSRアイテムを獲得する確率は96.97％、SSRアイテムを獲得する確率は3.03％です。\n\n<Title:【特別な説明】>\n·覚醒でSR命輪を獲得した場合、同時に5個の根源の澱を副産物として獲得します；R命輪を獲得した場合、同時に1個の根源の澱を副産物として獲得します。\n·いかなる方法(覚醒、ショップ交換、システム贈与などを含む)で第2〜16回目に同じSSR覚醒体を獲得した際、毎回1個の対応する覚醒体の欠片と50個の根源の澱に変換されます；第17回目以降の獲得では、非限定SSR覚醒体は「灵魂回溯碎片」×1と「根源の澱」×150に変換され、限定SSR覚醒体は「灵魂回溯碎片」×2と「根源の澱」×250に変換されます。しかし、任意の方法(原質楽園、返魂のコア、原型視界などを含む)やランダムな方法(原質捕獲·忘却篇など)で覚醒体または溢れた覚醒体の欠片を獲得した場合、根源の澱には変換されません。\n·今回の覚醒は【キャラクターイベント覚醒】に属し、任意の【キャラクターイベント覚醒】において、保底覚醒回数は共同で累積され、他の覚醒タイプの保底覚醒回数とは独立して統計されます。\n\n"
  },
